select pg_advisory_xact_lock(7311001);

-- ===== supabase/updates/20261118000200_m3g_account_reset.sql =====
-- ===== idempotent copy of migrations/20261118000200_m3g_account_reset.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · M3g · 0200 · Reset and delete the own account
-- =============================================================================
-- reset_account(): back to the state of a freshly signed-up player. Kept: the
-- auth user, nickname, avatar, settings, notification preferences, friendships,
-- push subscriptions, idempotency journal, rate limits and anti-cheat records.
-- delete_account(): the same cleanup, then the auth user (and with it the
-- profile) is deleted; the nickname is free again.
--
-- The ledger, trades, orders and positions are immutable or referenced by
-- immutable history. They outlive a deleted player: their player columns keep
-- the UUID as an anonymous reference (no foreign key any more), the player's
-- ledger accounts stay with balance 0 and are frozen. Every money movement of
-- the cleanup is a balanced posting against the state (treasury; the mint
-- before the world genesis).
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. History outlives a deleted player
-- ---------------------------------------------------------------------------
alter table public.ledger_accounts     drop constraint if exists ledger_accounts_owner_player_fk;
alter table public.ledger_transactions drop constraint if exists ledger_transactions_initiated_by_fk;
alter table public.trades              drop constraint if exists trades_player_id_fkey;
alter table public.orders              drop constraint if exists orders_player_id_fkey;
alter table public.positions           drop constraint if exists positions_player_id_fkey;
comment on column public.ledger_accounts.owner_player_id is
  'Owning player. No foreign key: the accounts of a deleted player stay (balance 0, frozen) so the ledger history remains complete.';

alter table public.player_private add column if not exists account_reset_at timestamptz;
comment on column public.player_private.account_reset_at is 'Last reset_account() (game time); trades up to it are no longer shown to the player.';

-- ---------------------------------------------------------------------------
-- B. Shared cleanup (internal)
-- ---------------------------------------------------------------------------
-- Ends everything game-related of a player and returns the cash to the state.
-- Leaves profile, settings and ledger accounts in place (balance 0).
create or replace function public.account_wipe(p_player uuid, p_key text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_nick    text;
  v_company uuid;
  v_state   uuid := public.ledger_system_account(case when public.money_genesis_done() then 'treasury' else 'mint' end);
  v_bal     bigint;
  r         record;
begin
  perform public.lock_player_accounts(p_player);
  select p.nickname into v_nick from public.profiles p where p.id = p_player for update;

  -- own company: open share offers are settled first, then it is dissolved like close_company
  select pc.company_id into v_company from public.player_companies pc where pc.founder_id = p_player and pc.status = 'active';
  if v_company is not null then
    for r in select o.id from public.company_share_offers o where o.company_id = v_company and o.status = 'open' order by o.id loop
      perform public.close_share_offer(r.id);
    end loop;
    perform public.company_dissolve(v_company, 'closed');
  end if;

  -- subscriptions to other companies' open offers lapse (the money stays with the company)
  for r in select s.offer_id, sum(s.shares_e6)::bigint as q from public.offer_subscriptions s
            join public.company_share_offers o on o.id = s.offer_id and o.status = 'open'
           where s.player_id = p_player group by s.offer_id order by s.offer_id loop
    update public.company_share_offers set shares_subscribed_e6 = greatest(0, shares_subscribed_e6 - r.q) where id = r.offer_id;
  end loop;

  -- job: wages up to now, then ended without notice or fee
  for r in select pj.id, pj.company_id from public.player_jobs pj where pj.player_id = p_player and pj.status = 'active' order by pj.id loop
    perform public.accrue_job_salary(r.id);
    update public.player_jobs set status = 'ended', ended_at = now(), end_reason = 'quit', notice_ends_at = null where id = r.id;
    perform public.company_system_message(r.company_id, v_nick || ' hat das Unternehmen verlassen.');
  end loop;

  -- open orders release their reservations; holdings are given up
  for r in select o.id from public.orders o
            where o.player_id = p_player and o.status in ('pending', 'open', 'partially_filled') order by o.id loop
    perform public.cancel_order_internal(r.id);
  end loop;
  update public.positions
     set status = 'closed', closed_at = now(), quantity_e6 = 0, reserved_quantity_e6 = 0, cost_basis_cents = 0,
         margin_cents = 0, borrowed_cents = 0, liquidation_price_e4 = null
   where player_id = p_player and status = 'open';

  -- game state of the player
  for r in select * from (values
             ('position_lots', 'player_id'), ('xp_events', 'player_id'), ('xp_daily_counters', 'player_id'),
             ('vault_claims', 'player_id'), ('daily_logins', 'player_id'), ('player_missions', 'player_id'),
             ('player_achievements', 'player_id'), ('player_cosmetics', 'player_id'), ('player_lifestyle_items', 'player_id'),
             ('player_random_events', 'player_id'), ('player_bankruptcies', 'player_id'), ('margin_events', 'player_id'),
             ('financing_charges', 'player_id'), ('player_tax_years', 'player_id'), ('distribution_payouts', 'player_id'),
             ('watchlist_items', 'player_id'), ('portfolio_snapshots', 'player_id'), ('stock_option_grants', 'player_id'),
             ('loans', 'player_id'), ('cap_table_entries', 'player_id'), ('share_lockups', 'player_id'),
             ('capital_injections', 'player_id'), ('takeover_offers', 'bidder_player_id'), ('angel_offers', 'investor_player_id'),
             ('ipo_subscriptions', 'player_id'), ('shareholder_vote_ballots', 'player_id'), ('reputation_events', 'player_id'),
             ('insider_violations', 'player_id'), ('salary_payouts', 'player_id'), ('work_tasks', 'player_id'),
             ('salary_negotiations', 'player_id'), ('player_work_tasks', 'player_id'), ('player_jobs', 'player_id'),
             ('job_offers', 'to_player_id'), ('job_applications', 'player_id'), ('player_skills', 'player_id'),
             ('player_skill_points', 'player_id'), ('daily_reward_claims', 'player_id'), ('player_loans', 'player_id'),
             ('offer_subscriptions', 'player_id'), ('notifications', 'player_id'), ('feed_items', 'actor_id'),
             ('league_entries', 'player_id'), ('league_entry_baselines', 'player_id'), ('company_logo_reports', 'reporter_id'),
             ('player_unlocks', 'player_id')
           ) as t(tbl, col) loop
    execute format('delete from public.%I where %I = $1', r.tbl, r.col) using p_player;
  end loop;
  delete from public.rich_list_snapshots where entity_kind = 'player' and entity_id = p_player;

  -- money back to the state: one balanced posting per account
  for r in select a.id from public.ledger_accounts a where a.owner_player_id = p_player and a.balance_cents > 0 order by a.id loop
    select a.balance_cents into v_bal from public.ledger_accounts a where a.id = r.id;
    perform public.ledger_transfer(r.id, v_state, v_bal, 'transfer', 'Konto zurückgesetzt', 'profile', p_player,
                                   p_key || ':' || r.id::text, p_player);
  end loop;

  update public.profiles
     set level = 1, xp_total = 0, reputation = 50, title_key = null, frame_key = null,
         bankrupt_until = null, founding_locked_until = null
   where id = p_player;
  update public.player_private
     set founding_ban_until = null, bankruptcy_count = 0, career_experience_minutes = 0, ipo_investment_limit_cents = null,
         tutorial_completed_at = null, tax_loss_pot_cents = 0
   where player_id = p_player;
end;
$$;
comment on function public.account_wipe(uuid, text) is 'Internal: cleanup shared by reset_account() and delete_account().';

-- Checks the confirmation (the own nickname, case-insensitive, trimmed).
create or replace function public.account_confirm(p_player uuid, p_confirm text)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if p_confirm is null
     or not exists (select 1 from public.profiles p where p.id = p_player and lower(p.nickname) = lower(btrim(p_confirm))) then
    raise exception using errcode = 'NX061', message = 'confirm_mismatch';
  end if;
end;
$$;

-- ---------------------------------------------------------------------------
-- C. RPCs
-- ---------------------------------------------------------------------------
create or replace function public.reset_account(p_request_id uuid, p_confirm text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player      uuid;
  v_replay      jsonb;
  v_now         timestamptz := public.game_now();
  v_start_cents bigint := greatest(public.config_bigint('economy', '{startingCapitalCents}', 1000000), 0);
  v_vault_hours double precision := greatest(0, least(
                    public.config_double('economy', '{vaultInitialHours}', 2),
                    public.config_double('economy', '{vaultCapHours}', 8)));
  v_key         text;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'reset_account');
  if v_replay is not null then
    return v_replay;
  end if;
  perform public.account_confirm(v_player, p_confirm);
  v_key := 'reset:' || v_player::text || ':' || p_request_id::text;

  perform public.account_wipe(v_player, v_key);

  -- what sign-up grants (handle_new_user)
  update public.vaults
     set accrual_started_at = public.game_now() - make_interval(secs => v_vault_hours * 3600),
         last_claimed_at = null, total_claimed_cents = 0, full_notified_at = null
   where player_id = v_player;
  update public.login_streaks
     set current_streak = 0, longest_streak = 0, last_login_day = null, freeze_tokens = 1, freeze_granted_week = null,
         reward_cycle_day = 0, reward_last_day = null
   where player_id = v_player;
  insert into public.player_unlocks (player_id, unlock_key)
  select v_player, u.key from public.unlocks u where u.level <= 1
  on conflict do nothing;
  update public.player_private set account_reset_at = v_now where player_id = v_player;
  if v_start_cents > 0 then
    perform public.state_payout(v_player, v_start_cents, 0, 'restart_capital', 'Starting capital (account reset)',
                                'profile', v_player, v_key || ':start');
  end if;

  return public.request_complete(v_player, p_request_id, jsonb_build_object('ok', true, 'reset_at', v_now));
end;
$$;
comment on function public.reset_account(uuid, text) is 'RPC: resets the own account to a fresh start (p_confirm = own nickname).';

create or replace function public.delete_account(p_confirm text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
begin
  v_player := public.require_player();
  perform public.account_confirm(v_player, p_confirm);
  perform public.account_wipe(v_player, 'delete:' || v_player::text);
  update public.ledger_accounts set is_frozen = true where owner_player_id = v_player;
  delete from auth.users where id = v_player;
  return jsonb_build_object('ok', true);
end;
$$;
comment on function public.delete_account(text) is 'RPC: deletes the own account (p_confirm = own nickname); the nickname is free again.';

-- ---------------------------------------------------------------------------
-- D. Portfolio: trades before the last reset are no longer shown
-- ---------------------------------------------------------------------------
create or replace function public.get_my_portfolio()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player    uuid;
  v_cash      bigint;
  v_reserved  bigint;
  v_positions jsonb;
  v_value     bigint;
  v_bid_value bigint;
  v_orders    jsonb;
  v_trades    jsonb;
  v_prof      public.profiles;
  v_priv      public.player_private;
  v_level     jsonb;
  v_days      double precision := public.config_double('names', '{nicknameChangeDays}', 60);
  v_today     date := (public.game_now() at time zone 'Europe/Berlin')::date;
  v_streak    integer;
  ls          public.login_streaks;
begin
  v_player := public.require_player();
  select * into v_priv from public.player_private where player_id = v_player;
  select coalesce(sum(a.balance_cents) filter (where a.kind = 'player_cash'), 0),
         coalesce(sum(a.balance_cents) filter (where a.kind = 'player_reserve'), 0)
    into v_cash, v_reserved
    from public.ledger_accounts a where a.owner_player_id = v_player;

  select coalesce(jsonb_agg(jsonb_build_object(
           'ticker', x.ticker, 'name', x.name, 'kind', x.kind, 'quantity_e6', x.quantity_e6,
           'reserved_quantity_e6', x.reserved_quantity_e6, 'avg_price_e4', x.avg_entry_price_e4,
           'last_price_e4', x.last_price_e4, 'market_value_cents', x.mv, 'cost_basis_cents', x.cost_basis_cents,
           'unrealized_pnl_cents', x.mv - x.cost_basis_cents, 'realized_pnl_cents', x.realized_pnl_cents,
           'change_bps', x.change_bps, 'opened_at', x.opened_at)
           order by x.mv desc), '[]'::jsonb),
         coalesce(sum(x.mv), 0)::bigint,
         coalesce(sum(x.bv), 0)::bigint
    into v_positions, v_value, v_bid_value
    from (select s.ticker, s.name, s.kind, p.quantity_e6, p.reserved_quantity_e6, p.avg_entry_price_e4, p.cost_basis_cents,
                 p.realized_pnl_cents, p.opened_at, q.last_price_e4, q.change_bps,
                 public.value_cents(p.quantity_e6, q.last_price_e4) as mv,
                 public.value_cents(p.quantity_e6, coalesce(q.bid_e4, q.last_price_e4)) as bv
            from public.positions p
            join public.securities s on s.id = p.security_id
            join public.security_quotes q on q.security_id = p.security_id
           where p.player_id = v_player and p.status = 'open' and p.quantity_e6 > 0) x;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', o.id, 'ticker', s.ticker, 'side', o.side, 'type', o.type, 'quantity_e6', o.quantity_e6,
           'filled_quantity_e6', o.filled_quantity_e6, 'limit_price_e4', o.limit_price_e4, 'status', o.status,
           'reserved_cents', o.reserved_cents, 'created_at', o.created_at)
           order by o.created_at desc), '[]'::jsonb)
    into v_orders
    from public.orders o join public.securities s on s.id = o.security_id
   where o.player_id = v_player and o.status in ('open', 'partially_filled');

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', t.id, 'ticker', t.ticker, 'side', t.side, 'quantity_e6', t.quantity_e6, 'price_e4', t.price_e4,
           'gross_cents', t.gross_cents, 'fee_cents', t.fee_cents, 'tax_cents', t.tax_cents,
           'realized_pnl_cents', t.realized_pnl_cents, 'xp_awarded', t.xp_awarded, 'executed_at', t.executed_at)
           order by t.executed_at desc), '[]'::jsonb)
    into v_trades
    from (select tr.*, s.ticker from public.trades tr join public.securities s on s.id = tr.security_id
           where tr.player_id = v_player and tr.executed_at > coalesce(v_priv.account_reset_at, '-infinity'::timestamptz)
           order by tr.executed_at desc limit 50) t;

  select * into v_prof from public.profiles where id = v_player;
  select * into ls from public.login_streaks where player_id = v_player;
  v_level := public.level_progress(v_prof.xp_total);
  v_streak := case when ls.last_login_day >= v_today - 1 then ls.current_streak
                   when ls.last_login_day = v_today - 2 and ls.freeze_tokens > 0 then ls.current_streak
                   else 0 end;

  return jsonb_build_object(
    'cash_cents',            v_cash,
    'reserved_cents',        v_reserved,
    'positions_value_cents', v_value,
    'total_cents',           v_cash + v_reserved + v_value,
    'net_worth_cents',       v_cash + v_reserved + v_bid_value,
    'loss_pot_cents',        coalesce(v_priv.tax_loss_pot_cents, 0),
    'vault',                 public.vault_status(v_player) - 'accrued_seconds' - 'base_rate_cents_per_hour',
    'positions',             v_positions,
    'open_orders',           v_orders,
    'recent_trades',         v_trades,
    'level',                 v_prof.level,
    'xp_total',              v_prof.xp_total,
    'xp_into_level',         (v_level ->> 'xp_into_level')::bigint,
    'xp_for_next',           (v_level ->> 'xp_for_next')::bigint,
    'tutorial_completed',    v_priv.tutorial_completed_at is not null,
    'nickname',              v_prof.nickname,
    'nickname_change_available_at',
                             case when v_prof.nickname_changed_at is null
                                    or v_prof.nickname_changed_at + make_interval(secs => v_days * 86400) <= now() then null
                                  else v_prof.nickname_changed_at + make_interval(secs => v_days * 86400) end,
    'missions_claimable',    (select count(*) from public.player_missions m
                               where m.player_id = v_player and m.status = 'completed'
                                 and (m.expires_at is null or m.expires_at > public.game_now()))::integer,
    'streak_days',           coalesce(v_streak, 0),
    'avatar_key',            coalesce(v_prof.avatar_key, 'rookie'),
    'skill_points_free',     coalesce((select sp.free_points from public.player_skill_points sp where sp.player_id = v_player), 0),
    'daily_reward_claimable', not exists (select 1 from public.daily_reward_claims c
                                           where c.player_id = v_player
                                             and c.claim_day = (public.game_now() at time zone 'Europe/Berlin')::date),
    'company_value_cents',   public.player_company_value_cents(v_player),
    'debt_cents',            public.player_debt_cents(v_player),
    'debt_withholding_bps',  public.config_double('startups', '{insolvency,loanWithholdingBps}', 5000)::integer,
    'founding_locked_until', case when v_prof.founding_locked_until > now() then v_prof.founding_locked_until end,
    'server_time',           public.game_now());
end;
$$;

-- ---------------------------------------------------------------------------
-- E. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.account_wipe(uuid, text)', 'public.account_confirm(uuid, text)',
    'public.reset_account(uuid, text)', 'public.delete_account(text)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  foreach f in array array['public.reset_account(uuid, text)', 'public.delete_account(text)'] loop
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end;
$$;

-- ===== supabase/updates/20261119000100_m3h_ai_skills_training.sql =====
-- ===== idempotent copy of migrations/20261119000100_m3h_ai_skills_training.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · M3h · 0100 · AI workers for stage skills, trainings from a team size (ADR-071)
-- =============================================================================
-- player_companies.ai_worker_skills: one entry (skill key) per AI worker hired
-- for a stage skill; AI workers beyond the array length are general ones.
-- Invariant: cardinality(ai_worker_skills) <= ai_workers, no duplicates. A
-- trigger keeps it for every path that lowers ai_workers (set_ai_workers,
-- quarter close in distress, dissolution, account reset): general AI workers go
-- first, then skilled ones from the end of the array.
-- companyStage counts skills covered by AI workers like learned team skills.
-- Trainings unlock from startups.training.fromEmployees (headcount).
-- Error keys (M3h): skill_already_covered NX062, training_locked NX063.
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. Schema
-- ---------------------------------------------------------------------------
alter table public.player_companies add column if not exists ai_worker_skills text[] not null default '{}';
comment on column public.player_companies.ai_worker_skills is
  'Stage skill keys covered by AI workers (one AI worker each, hire order); AI workers beyond its length are general.';

-- keeps the invariant: no nulls or duplicates (first one wins), at most one entry per AI worker
create or replace function public.player_companies_ai_skills_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.ai_worker_skills := coalesce((select array_agg(x.s order by x.o)
                                      from (select u.s, min(u.o) as o
                                              from unnest(new.ai_worker_skills) with ordinality u(s, o)
                                             where u.s is not null
                                             group by u.s) x), '{}'::text[]);
  if cardinality(new.ai_worker_skills) > new.ai_workers then
    new.ai_worker_skills := new.ai_worker_skills[1:greatest(new.ai_workers, 0)];
  end if;
  return new;
end;
$$;
comment on function public.player_companies_ai_skills_guard() is
  'Trigger: ai_worker_skills without duplicates and never longer than ai_workers (skilled AI workers are dropped from the end).';

do $$
begin
  if not exists (select 1 from pg_trigger where tgname = 'ai_worker_skills_guard' and tgrelid = 'public.player_companies'::regclass) then
    create trigger ai_worker_skills_guard before insert or update of ai_workers, ai_worker_skills on public.player_companies
      for each row execute function public.player_companies_ai_skills_guard();
  end if;
  if not exists (select 1 from pg_constraint where conname = 'player_companies_ai_worker_skills_check'
                                              and conrelid = 'public.player_companies'::regclass) then
    alter table public.player_companies add constraint player_companies_ai_worker_skills_check
      check (cardinality(ai_worker_skills) <= ai_workers);
  end if;
  grant select (ai_worker_skills) on public.player_companies to authenticated;
end;
$$;

-- ---------------------------------------------------------------------------
-- B. Stages: AI workers cover skills like team members
-- ---------------------------------------------------------------------------
-- companyStage: highest stage whose skills (and those of all earlier stages) the team or an AI worker covers
create or replace function public.company_stage(p_company uuid)
returns integer
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_stages jsonb := coalesce(public.company_product(p_company) -> 'stages', '[]'::jsonb);
  v_have   text[];
  v_stage  integer := 0;
  st       jsonb;
begin
  select coalesce(array_agg(distinct t.skill_key), '{}') into v_have from public.company_team_skills(p_company) t;
  v_have := v_have || coalesce((select pc.ai_worker_skills from public.player_companies pc where pc.company_id = p_company),
                               '{}'::text[]);
  for st in select x from jsonb_array_elements(v_stages) x loop
    exit when exists (select 1 from jsonb_array_elements_text(st) k where not (k = any (v_have)));
    v_stage := v_stage + 1;
  end loop;
  return v_stage;
end;
$$;

-- stages for COMPANY: [{stage, reached, skills: [{key, covered_by, covered_by_ai}]}]
-- covered_by: nickname of the first team member with the skill; covered_by_ai: only an AI worker covers it
create or replace function public.company_stages_json(p_company uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'stage', o,
           'reached', o <= v.stage,
           'skills', (select coalesce(jsonb_agg(jsonb_build_object(
                                'key', k,
                                'covered_by', cb.nickname,
                                'covered_by_ai', cb.nickname is null and k = any (v.ai)) order by ko), '[]'::jsonb)
                        from jsonb_array_elements_text(st) with ordinality y(k, ko)
                        left join lateral (select t.nickname from public.company_team_skills(p_company) t
                                            where t.skill_key = k order by t.ord limit 1) cb on true)) order by o), '[]'::jsonb)
    from jsonb_array_elements(coalesce(public.company_product(p_company) -> 'stages', '[]'::jsonb)) with ordinality x(st, o),
         (select public.company_stage(p_company) as stage,
                 coalesce((select pc.ai_worker_skills from public.player_companies pc where pc.company_id = p_company),
                          '{}'::text[]) as ai) v;
$$;

-- ---------------------------------------------------------------------------
-- C. RPCs: hire and dismiss AI workers
-- ---------------------------------------------------------------------------
-- hire_ai_workers: p_count general AI workers, or (p_skill) one AI worker for a stage skill of the product
create or replace function public.hire_ai_workers(p_request_id uuid, p_count integer, p_skill text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
  pc        public.player_companies;
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null or p_count is null or p_count < 1 or p_count > 1000
     or (p_skill is not null and p_count <> 1) then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'hire_ai_workers');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into pc from public.player_companies where company_id = v_company for update;
  if p_skill is not null then
    if not exists (select 1
                     from jsonb_array_elements(coalesce(public.company_product(v_company) -> 'stages', '[]'::jsonb)) st,
                          jsonb_array_elements_text(st) k
                    where k = p_skill) then
      perform public.api_error('invalid_argument');
    end if;
    if p_skill = any (pc.ai_worker_skills) then
      raise exception using errcode = 'NX062', message = 'skill_already_covered';
    end if;
  end if;
  if pc.ai_workers + p_count
     + (select count(*) from public.player_jobs j where j.company_id = v_company and j.status = 'active')
     > (public.company_tier_cfg(pc.tier) ->> 'maxEmployees')::integer then
    perform public.api_error('employee_limit');
  end if;
  update public.player_companies
     set ai_workers = ai_workers + p_count,
         ai_worker_skills = case when p_skill is null then ai_worker_skills else ai_worker_skills || p_skill end
   where company_id = v_company;
  perform public.company_full_time_check(v_company);
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_company)));
end;
$$;
comment on function public.hire_ai_workers(uuid, integer, text) is
  'RPC (founder): hires p_count general AI workers, or one AI worker that covers the stage skill p_skill.';

-- dismiss_ai_worker: the one covering p_skill, otherwise a general one (none left: the last skilled one)
create or replace function public.dismiss_ai_worker(p_request_id uuid, p_skill text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
  pc        public.player_companies;
  v_n       integer;
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'dismiss_ai_worker');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into pc from public.player_companies where company_id = v_company for update;
  v_n := cardinality(pc.ai_worker_skills);
  if p_skill is not null then
    if not (p_skill = any (pc.ai_worker_skills)) then
      perform public.api_error('invalid_argument');
    end if;
    update public.player_companies
       set ai_workers = ai_workers - 1, ai_worker_skills = array_remove(ai_worker_skills, p_skill)
     where company_id = v_company;
  elsif pc.ai_workers <= 0 then
    perform public.api_error('invalid_argument');
  elsif pc.ai_workers > v_n then
    update public.player_companies set ai_workers = ai_workers - 1 where company_id = v_company;
  else
    update public.player_companies
       set ai_workers = ai_workers - 1, ai_worker_skills = ai_worker_skills[1:v_n - 1]
     where company_id = v_company;
  end if;
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_company)));
end;
$$;
comment on function public.dismiss_ai_worker(uuid, text) is
  'RPC (founder): dismisses the AI worker covering p_skill, otherwise a general one (or else the last skilled one).';

-- ---------------------------------------------------------------------------
-- D. Trainings from a team size
-- ---------------------------------------------------------------------------
create or replace function public.train_employee(p_request_id uuid, p_player_job_id uuid, p_skill_key text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  j        public.player_jobs;
  v_node   jsonb;
  v_tr     jsonb;
  v_cost   bigint;
  v_acc    uuid;
  v_bal    bigint;
  v_new    bigint;
begin
  select * into j from public.player_jobs where id = p_player_job_id;
  if j.id is null or j.status <> 'active' then
    perform public.require_player();
    perform public.api_error('no_active_job');
  end if;
  v_player := public.require_company_owner(j.company_id);
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'train_employee');
  if v_replay is not null then
    return v_replay;
  end if;
  if public.company_headcount(j.company_id) < public.config_double('startups', '{training,fromEmployees}', 5) then
    raise exception using errcode = 'NX063', message = 'training_locked';
  end if;
  v_node := public.skill_node(p_skill_key);
  if v_node is null then
    perform public.api_error('skill_unknown');
  end if;
  if exists (select 1 from public.player_skills s where s.player_id = j.player_id and s.skill_key = p_skill_key) then
    perform public.api_error('skill_learned');
  end if;
  v_tr := public.training_for((v_node ->> 'tier')::integer);
  v_cost := (v_tr ->> 'cost_cents')::bigint;
  v_acc := public.company_cash_account(j.company_id);
  select a.balance_cents into v_bal from public.ledger_accounts a where a.id = v_acc for update;
  if coalesce(v_bal, 0) < v_cost then
    perform public.api_error('insufficient_funds');
  end if;
  if v_cost > 0 then
    perform public.ledger_transfer(v_acc, public.ledger_system_account('households'), v_cost, 'company_costs',
                                   'Schulung ' || p_skill_key, 'player_job', j.id,
                                   'training:' || j.id::text || ':' || p_skill_key, v_player);
  end if;
  insert into public.player_skills (player_id, skill_key) values (j.player_id, p_skill_key);
  perform public.accrue_job_salary(j.id);
  v_new := round(j.salary_cents_per_hour * (1 + (v_tr ->> 'raise_bps')::integer / 10000.0))::bigint;
  update public.player_jobs set salary_cents_per_hour = v_new where id = j.id;
  perform public.company_system_message(j.company_id,
    (select pr.nickname from public.profiles pr where pr.id = j.player_id) || ' hat eine Schulung abgeschlossen.');
  return public.request_complete(v_player, p_request_id, jsonb_build_object(
    'skill_key', p_skill_key, 'cost_cents', v_cost, 'salary_cents_per_hour', v_new));
end;
$$;

-- ---------------------------------------------------------------------------
-- E. COMPANY: ai_worker_skills and training_from
-- ---------------------------------------------------------------------------
create or replace function public.company_state(p_company uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  pc       public.player_companies;
  c        public.companies;
  v_team   jsonb;
  v_tier   jsonb;
  v_sb     jsonb;
  v_level  integer;
  v_cash   bigint;
  v_spread double precision;
  v_last   jsonb;
  v_hist   jsonb;
  v_cost   bigint;
begin
  select * into pc from public.player_companies where company_id = p_company;
  if pc.company_id is null then
    return null;
  end if;
  select * into c from public.companies where id = p_company;
  v_team := public.player_company_team(p_company);
  v_tier := public.company_tier_cfg(pc.tier);
  v_sb := public.company_tier_cfg('small_business');
  select p.level into v_level from public.profiles p where p.id = pc.founder_id;
  v_cash := coalesce((select a.balance_cents from public.ledger_accounts a where a.owner_company_id = p_company and a.kind = 'company_cash'), 0);
  v_spread := public.config_double('startups', '{estimate,initialSpread}', 2.3)
            * power(public.config_double('startups', '{estimate,decayPerQuarter}', 0.85), pc.quarters_active);
  select jsonb_build_object(
           'label', r.label, 'demand_cents', r.demand_cents, 'capacity_cents', r.capacity_cents,
           'revenue_cents', r.revenue_cents, 'cogs_cents', r.cogs_cents, 'fixed_cents', r.fixed_cents,
           'ai_worker_cents', r.ai_worker_cents, 'marketing_cents', r.marketing_cents, 'wages_cents', r.wages_cents,
           'operating_profit_cents', r.operating_profit_cents, 'utilization_bps', r.utilization_bps,
           'bonus_cents', r.bonus_cents)
    into v_last
    from public.player_company_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
   where r.company_id = p_company order by gq.ends_at desc limit 1;
  select coalesce(jsonb_agg(jsonb_build_object('label', h.label, 'revenue_cents', h.revenue_cents,
                                               'profit_cents', h.operating_profit_cents) order by h.ends_at), '[]'::jsonb)
    into v_hist
    from (select r.label, r.revenue_cents, r.operating_profit_cents, gq.ends_at
            from public.player_company_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
           where r.company_id = p_company order by gq.ends_at desc limit 12) h;
  v_cost := public.company_upgrade_cost(pc.tier);
  return jsonb_build_object(
    'id', c.id,
    'name', c.name,
    'idea', pc.idea,
    'sector', c.sector_key,
    'color', c.brand_color,
    'logo', public.company_logo(p_company),
    'logo_hidden', pc.logo_hidden,
    'founder_has_job', exists (select 1 from public.player_jobs x where x.player_id = pc.founder_id and x.status = 'active'),
    'full_time_from', public.config_double('startups', '{fullTimeFromEmployees}', 5)::integer,
    'training_from', public.config_double('startups', '{training,fromEmployees}', 5)::integer,
    'headcount', public.company_headcount(p_company),
    'tier', pc.tier,
    'founded_at', c.founded_at,
    'cash_cents', v_cash,
    'value_cents', public.company_value_cents(p_company),
    'unpaid_cents', pc.unpaid_cents,
    'distress', pc.distress,
    'distress_quarters', pc.distress_quarters,
    'grace_quarters', public.config_double('startups', '{insolvency,graceQuarters}', 4)::integer,
    'pay_factor_bps', pc.pay_factor_bps,
    'product_key', public.company_product(p_company) ->> 'key',
    'stage', (v_team ->> 'stage')::integer,
    'stages', public.company_stages_json(p_company),
    'awareness_bps', round(pc.awareness * 10000)::integer,
    'quality_bps', round(pc.quality * 10000)::integer,
    'quarters_active', pc.quarters_active,
    'estimate_low_cents', round(pc.potential_annual_cents
                                * exp(-v_spread * (0.3 + 0.7 * public.uniform_from_text(pc.company_id::text || ':' || pc.quarters_active || ':low'))))::bigint,
    'estimate_high_cents', round(pc.potential_annual_cents
                                 * exp(v_spread * (0.3 + 0.7 * public.uniform_from_text(pc.company_id::text || ':' || pc.quarters_active || ':high'))))::bigint,
    'marketing_cents_per_quarter', pc.marketing_cents_per_quarter,
    'ai_workers', pc.ai_workers,
    'ai_worker_cost_cents', public.config_bigint('startups', '{aiWorkerCostCentsPerQuarter}', 70000),
    'ai_worker_skills', to_jsonb(pc.ai_worker_skills),
    'max_employees', (v_tier ->> 'maxEmployees')::integer,
    'employees', (v_team ->> 'employees')::integer,
    'open_postings', (select count(*) from public.job_postings jp where jp.company_id = p_company and jp.status = 'open')::integer,
    'pending_applications', (select count(*) from public.job_applications a join public.job_postings jp on jp.id = a.posting_id
                              where jp.company_id = p_company and a.status = 'pending')::integer,
    'founder_productivity_bps', (v_team ->> 'founder_productivity_bps')::integer,
    'team_productivity_bps', (v_team ->> 'team_productivity_bps')::integer,
    'capacity_cents', (v_team ->> 'capacity_cents')::bigint,
    'next_quarter_at', coalesce((public.current_game_quarter()).ends_at, public.game_now()),
    'can_upgrade', public.company_next_tier(pc.tier) is not null
                   and coalesce(v_level, 1) >= (public.company_tier_cfg(public.company_next_tier(pc.tier)) ->> 'minLevel')::integer,
    'listing', public.company_listing_json(p_company, pc.founder_id),
    'can_go_public', c.phase = 'private' and public.company_open_offer(p_company) is null
                     and coalesce(public.config_jsonb('startups', '{ipo,fromTiers}'), '["small_business", "gmbh"]'::jsonb) ? pc.tier
                     and coalesce(v_level, 1) >= public.config_double('startups', '{ipo,minLevel}', 12),
    'can_capital_increase', c.phase = 'listed' and public.company_open_offer(p_company) is null,
    'upgrade_cost_cents', v_cost,
    'last_quarter', v_last,
    'history', v_hist);
end;
$$;

-- ---------------------------------------------------------------------------
-- F. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.player_companies_ai_skills_guard()', 'public.company_stage(uuid)', 'public.company_stages_json(uuid)',
    'public.hire_ai_workers(uuid, integer, text)', 'public.dismiss_ai_worker(uuid, text)',
    'public.train_employee(uuid, uuid, text)', 'public.company_state(uuid)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  foreach f in array array[
    'public.hire_ai_workers(uuid, integer, text)', 'public.dismiss_ai_worker(uuid, text)', 'public.train_employee(uuid, uuid, text)'
  ] loop
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end;
$$;

-- ===== supabase/updates/20261120000100_m3i_hourly_ranking.sql =====
-- ===== idempotent copy of migrations/20261120000100_m3i_hourly_ranking.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · M3i · 0100 · Hourly operations (ADR-072) and company ranking (ADR-074)
-- =============================================================================
-- Player companies earn every hour (docs/COMPANY_GROWTH.md, section 2). Mirrors
-- closeStartupHour in src/lib/sim/startup.ts:
--   demand/h   = potential / 4 / quarterHours × awareness × (0.5 + 0.5 × quality) × exp(noise × gauss)
--   capacity/h = team capacity × (1 + capacityBonusPerStage × stage) / quarterHours
--   revenue/h  = min(demand, capacity); goods = revenue × (1 − grossMargin)
--   wages due  = AI workers × aiWorkerWageCentsPerHour + Σ hourly contract wages of the players
--   payFactor  = due ≤ 0 ? 10000 : clamp(floor(max(0, gross) × 10000 / due), 0, 10000)
-- Players and AI workers are paid in the same hourly close with the same factor,
-- never with more than the hour earned (revenue − goods). Fixed costs and marketing
-- (per quarter / quarterHours) come from the company cash; what it cannot pay is
-- added to unpaid_cents (distress, ADR-058, still counted per quarter).
--
-- Player-company jobs are paid only in the hourly close (accrue_job_salary with
-- the hour's factor). accrue_salaries pays AI-company jobs only, in whole hours.
-- Paths that settle a job mid-hour (quit, fire, quit at once, dissolution,
-- account reset, training) keep calling accrue_job_salary, which pays the partial
-- hour at the company's current pay_factor_bps (the last hour's factor), capped
-- by the company cash.
--
-- The quarter close no longer books money for operations: it aggregates the
-- quarter's hours into player_company_reports (same columns), then updates
-- awareness and quality, pays the profit bonus (ADR-058) from the quarter's
-- profit, grants XP, counts distress quarters and posts the chat line.
--
-- get_company_ranking (ADR-074): player companies by value (listed: market value),
-- with scope 'all' also the listed AI companies by market value.
-- Logos (ADR-076): set once (logo_locked NX064), forbidden symbols rejected
-- (logo_forbidden NX065, port of hasForbiddenSymbol).
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. Schema
-- ---------------------------------------------------------------------------
alter table public.player_companies add column if not exists last_hour_at timestamptz;
update public.player_companies set last_hour_at = date_trunc('hour', public.game_now()) where last_hour_at is null;
alter table public.player_companies alter column last_hour_at set default date_trunc('hour', public.game_now());
alter table public.player_companies alter column last_hour_at set not null;
comment on column public.player_companies.last_hour_at is
  'End of the last closed operating hour = start of the next hour to close (ADR-072).';
comment on column public.player_companies.pay_factor_bps is
  'Pay factor of the last closed operating hour (ADR-072); mid-hour settlements use it.';

create table if not exists public.player_company_hours (
  company_id              uuid not null references public.player_companies (company_id) on delete cascade,
  hour_start              timestamptz not null,
  game_quarter_id         bigint references public.game_quarters (id),
  demand_cents            bigint not null,
  capacity_cents          bigint not null,
  revenue_cents           bigint not null check (revenue_cents >= 0),
  cogs_cents              bigint not null check (cogs_cents >= 0),
  fixed_cents             bigint not null check (fixed_cents >= 0),
  marketing_cents         bigint not null check (marketing_cents >= 0),
  player_wages_due_cents  bigint not null default 0 check (player_wages_due_cents >= 0),
  player_wages_paid_cents bigint not null default 0 check (player_wages_paid_cents >= 0),
  ai_wages_due_cents      bigint not null default 0 check (ai_wages_due_cents >= 0),
  ai_wages_paid_cents     bigint not null default 0 check (ai_wages_paid_cents >= 0),
  pay_factor_bps          integer not null check (pay_factor_bps between 0 and 10000),
  paid_costs_cents        bigint not null default 0 check (paid_costs_cents >= 0),
  unpaid_added_cents      bigint not null default 0 check (unpaid_added_cents >= 0),
  profit_cents            bigint not null,
  created_at              timestamptz not null default now(),
  primary key (company_id, hour_start)
);
alter table public.player_company_hours enable row level security;
create index if not exists player_company_hours_quarter_idx on public.player_company_hours (company_id, game_quarter_id);
create index if not exists player_company_hours_start_idx on public.player_company_hours (hour_start);
create index if not exists player_company_hours_game_quarter_idx on public.player_company_hours (game_quarter_id);
comment on table public.player_company_hours is
  'Operating hours of player companies (closeStartupHour, ADR-072); about the last 7 days are kept.';
comment on column public.player_company_hours.paid_costs_cents is 'Fixed costs and marketing paid from the cash this hour.';
comment on column public.player_company_hours.profit_cents is
  'Revenue − goods − player wages paid − AI wages paid − fixed costs − marketing.';

do $$
begin
  grant select (last_hour_at) on public.player_companies to authenticated;

  revoke all on public.player_company_hours from public, anon, authenticated;
  grant select on public.player_company_hours to authenticated;
  grant all on public.player_company_hours to service_role;
  drop policy if exists "members read" on public.player_company_hours;
  create policy "members read" on public.player_company_hours for select to authenticated
    using (exists (select 1 from public.player_companies pc
                    where pc.company_id = player_company_hours.company_id and pc.founder_id = (select auth.uid()))
           or exists (select 1 from public.player_jobs j
                       where j.company_id = player_company_hours.company_id and j.player_id = (select auth.uid())
                         and j.status = 'active'));
end;
$$;

-- ---------------------------------------------------------------------------
-- B. Wages: minutes a job can be paid up to a time (as in accrue_job_salary)
-- ---------------------------------------------------------------------------
create or replace function public.job_payable_minutes(p_job uuid, p_until timestamptz)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((
    select case when floor(extract(epoch from (p_until - j.last_paid_at)) / 60) < 1 then 0
                else least(floor(extract(epoch from (p_until - j.last_paid_at)) / 60)::integer,
                           greatest(0, (public.config_double('careers', '{paidHoursPerDayCap}', 12) * 60)::integer
                                       - case when j.paid_day = (p_until at time zone 'Europe/Berlin')::date
                                              then j.paid_minutes_today else 0 end)) end
      from public.player_jobs j
     where j.id = p_job and j.status = 'active'), 0);
$$;
comment on function public.job_payable_minutes(uuid, timestamptz) is
  'Minutes accrue_job_salary(p_job, p_until) would pay (elapsed whole minutes, limited by careers.paidHoursPerDayCap).';

-- AI-company jobs only, in whole hours; player-company jobs are paid in the hourly close (ADR-072)
create or replace function public.accrue_salaries(p_now timestamptz default null)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now   timestamptz := coalesce(p_now, public.game_now());
  r       record;
  v_whole integer;
  v_n     integer := 0;
begin
  for r in select j.id, j.player_id, j.last_paid_at
             from public.player_jobs j join public.companies c on c.id = j.company_id
            where j.status = 'active' and c.is_ai
            order by j.player_id loop
    v_whole := floor(extract(epoch from (v_now - r.last_paid_at)) / 3600)::integer;
    continue when v_whole < 1;
    perform public.lock_player_accounts(r.player_id);
    if public.accrue_job_salary(r.id, r.last_paid_at + make_interval(hours => v_whole)) > 0 then
      v_n := v_n + 1;
    end if;
  end loop;
  return v_n;
end;
$$;

-- ---------------------------------------------------------------------------
-- C. One operating hour of a player company (closeStartupHour)
-- ---------------------------------------------------------------------------
create or replace function public.player_company_close_hour(p_company uuid, p_hour_start timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  pc        public.player_companies;
  c         public.companies;
  v_su      jsonb := coalesce(public.config_jsonb('startups'), '{}'::jsonb);
  v_hours   double precision := greatest(1, public.config_double('time', '{quarterHours}', 6));
  v_start   timestamptz := date_trunc('hour', p_hour_start);
  v_end     timestamptz;
  v_qid     bigint;
  v_team    jsonb;
  v_tier    jsonb;
  v_stage   integer;
  v_demand  double precision;
  v_cap     double precision;
  v_rev     bigint;
  v_cogs    bigint;
  v_gross   bigint;
  v_aidue   bigint;
  v_aipaid  bigint;
  v_pdue    bigint := 0;
  v_ppaid   bigint := 0;
  v_due     bigint;
  v_factor  integer;
  v_fixed   bigint;
  v_mk      bigint;
  v_costs   bigint;
  v_paid    bigint := 0;
  v_unpaid  bigint := 0;
  v_settle  bigint := 0;
  v_cash    bigint;
  v_acc     uuid;
  v_hh      uuid;
  v_profit  bigint;
  v_until   timestamptz;
  k         text;
  j         record;
begin
  if p_company is null or p_hour_start is null then
    return null;
  end if;
  select * into pc from public.player_companies where company_id = p_company and status = 'active' for update;
  if pc.company_id is null then
    return null;
  end if;
  if exists (select 1 from public.player_company_hours h where h.company_id = p_company and h.hour_start = v_start) then
    update public.player_companies set last_hour_at = greatest(last_hour_at, v_start + interval '1 hour')
     where company_id = p_company and last_hour_at < v_start + interval '1 hour';
    return jsonb_build_object('company_id', p_company, 'hour_start', v_start, 'skipped', 'already_closed');
  end if;
  v_end := v_start + interval '1 hour';
  select * into c from public.companies where id = p_company;
  select gq.id into v_qid from public.game_quarters gq where gq.starts_at <= v_start and gq.ends_at > v_start;
  v_team := public.player_company_team(p_company);
  v_tier := public.company_tier_cfg(pc.tier);
  v_acc := public.company_cash_account(p_company);
  v_hh := public.ledger_system_account('households');
  k := 'pch:' || p_company::text || ':' || to_char(v_start at time zone 'UTC', 'YYYYMMDDHH24');

  -- sales of the hour with the quarter's awareness and quality
  v_stage := least(greatest(coalesce((v_team ->> 'stage')::integer, 0), 0),
                   greatest(jsonb_array_length(coalesce(v_su #> '{stages,awarenessCaps}', '[1]'::jsonb)) - 1, 0));
  v_demand := pc.potential_annual_cents / 4.0 / v_hours * pc.awareness * (0.5 + 0.5 * pc.quality)
            * exp(public.cfg_num(v_su, '{demandNoise}', 0.1) * public.gauss_random());
  v_cap := (v_team ->> 'team_productivity_bps')::double precision / 10000.0
         * public.cfg_num(v_su, array['capacityCentsPerProductivity', c.sector_key], 250000)
         * (1 + public.cfg_num(v_su, '{stages,capacityBonusPerStage}', 0.25) * v_stage) / v_hours;
  v_rev := round(least(v_demand, v_cap)::numeric)::bigint;
  -- closed money system: the households pay at most what they have
  v_rev := least(v_rev, greatest(0, coalesce((select a.balance_cents from public.ledger_accounts a where a.id = v_hh), 0)));
  v_cogs := round((v_rev * (1 - public.cfg_num(v_su, array['grossMargin', c.sector_key], 0.5)))::numeric)::bigint;
  v_gross := v_rev - v_cogs;

  -- wages due: AI workers and the hourly contract wages of the players (the founder draws no wage)
  v_aidue := pc.ai_workers * public.config_bigint('startups', '{aiWorkerWageCentsPerHour}', 12000);
  for j in select pj.id, pj.salary_cents_per_hour, pj.notice_ends_at from public.player_jobs pj
            where pj.company_id = p_company and pj.status = 'active' order by pj.id loop
    v_until := least(v_end, coalesce(j.notice_ends_at, v_end));
    v_pdue := v_pdue + j.salary_cents_per_hour * public.job_payable_minutes(j.id, v_until) / 60;
  end loop;
  v_due := v_aidue + v_pdue;
  -- never more than the hour earned; everyone gets the same share (ADR-072)
  v_factor := case when v_due <= 0 then 10000 else least(10000, greatest(0, v_gross) * 10000 / v_due)::integer end;
  v_aipaid := v_aidue * v_factor / 10000;

  -- money: revenue from the households, goods and AI wages back to them
  if v_rev > 0 then
    perform public.ledger_transfer(v_hh, v_acc, v_rev, 'company_revenue',
                                   'Umsatz ' || to_char(v_start at time zone 'Europe/Berlin', 'HH24') || ' Uhr',
                                   'company', p_company, k || ':revenue', pc.founder_id);
  end if;
  if v_cogs + v_aipaid > 0 then
    perform public.ledger_transfer(v_acc, v_hh, v_cogs + v_aipaid, 'company_costs', 'Wareneinsatz und KI-Kräfte',
                                   'company', p_company, k || ':goods', pc.founder_id);
  end if;
  -- players: the hour (up to the end of a notice) at contract wage x factor, with XP and branch minutes
  update public.player_companies set pay_factor_bps = v_factor where company_id = p_company;
  for j in select pj.id, pj.player_id, pj.notice_ends_at from public.player_jobs pj
            where pj.company_id = p_company and pj.status = 'active' order by pj.id loop
    v_until := least(v_end, coalesce(j.notice_ends_at, v_end));
    perform public.lock_player_accounts(j.player_id);
    v_ppaid := v_ppaid + public.accrue_job_salary(j.id, v_until);
  end loop;

  -- fixed costs and marketing from the cash; the rest becomes an open bill
  v_fixed := round(((v_tier ->> 'fixedCostCentsPerQuarter')::bigint / v_hours)::numeric)::bigint;
  v_mk := round((pc.marketing_cents_per_quarter / v_hours)::numeric)::bigint;
  v_costs := v_fixed + v_mk;
  select greatest(0, a.balance_cents) into v_cash from public.ledger_accounts a where a.id = v_acc;
  v_paid := least(v_costs, coalesce(v_cash, 0));
  if v_paid > 0 then
    perform public.ledger_transfer(v_acc, v_hh, v_paid, 'company_costs', 'Fixkosten und Marketing',
                                   'company', p_company, k || ':costs', pc.founder_id);
  end if;
  v_unpaid := v_costs - v_paid;
  if v_unpaid = 0 and pc.unpaid_cents > 0 then
    select greatest(0, a.balance_cents) into v_cash from public.ledger_accounts a where a.id = v_acc;
    v_settle := least(pc.unpaid_cents, coalesce(v_cash, 0));
    if v_settle > 0 then
      perform public.ledger_transfer(v_acc, v_hh, v_settle, 'company_costs', 'Offene Rechnungen',
                                     'company', p_company, k || ':settle', pc.founder_id);
    end if;
  end if;

  v_profit := v_rev - v_cogs - v_ppaid - v_aipaid - v_fixed - v_mk;
  update public.player_companies
     set unpaid_cents = pc.unpaid_cents + v_unpaid - v_settle,
         distress = pc.unpaid_cents + v_unpaid - v_settle > 0,
         last_hour_at = greatest(pc.last_hour_at, v_end)
   where company_id = p_company;
  insert into public.player_company_hours (company_id, hour_start, game_quarter_id, demand_cents, capacity_cents, revenue_cents,
                                           cogs_cents, fixed_cents, marketing_cents, player_wages_due_cents,
                                           player_wages_paid_cents, ai_wages_due_cents, ai_wages_paid_cents, pay_factor_bps,
                                           paid_costs_cents, unpaid_added_cents, profit_cents)
  values (p_company, v_start, v_qid, round(v_demand::numeric)::bigint, round(v_cap::numeric)::bigint, v_rev,
          v_cogs, v_fixed, v_mk, v_pdue, v_ppaid, v_aidue, v_aipaid, v_factor, v_paid, v_unpaid, v_profit);

  return jsonb_build_object('company_id', p_company, 'hour_start', v_start, 'quarter_id', v_qid, 'revenue_cents', v_rev,
                            'profit_cents', v_profit, 'pay_factor_bps', v_factor, 'player_wages_paid_cents', v_ppaid,
                            'ai_wages_paid_cents', v_aipaid, 'unpaid_added_cents', v_unpaid);
end;
$$;
comment on function public.player_company_close_hour(uuid, timestamptz) is
  'Closes one operating hour of a player company (closeStartupHour, ADR-072); idempotent per (company, hour).';

-- ---------------------------------------------------------------------------
-- D. Quarter close: aggregate the hours, then what stays quarterly
-- ---------------------------------------------------------------------------
create or replace function public.player_company_close_quarter(p_company uuid, p_quarter_id bigint)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  pc        public.player_companies;
  c         public.companies;
  q         public.game_quarters;
  v_su      jsonb := coalesce(public.config_jsonb('startups'), '{}'::jsonb);
  v_team    jsonb;
  v_target  double precision;
  v_quality double precision;
  v_mkq     bigint;
  v_half    double precision;
  v_gain    double precision := 0;
  v_aw      double precision;
  v_stage   integer;
  h         record;
  v_factor  integer;
  v_bwages  bigint;
  v_pool    bigint;
  v_weight  bigint;
  v_btotal  bigint := 0;
  v_bpaid   bigint := 0;
  v_b       bigint;
  v_cash    bigint;
  v_acc     uuid;
  v_xp      integer := 0;
  v_ai      integer;
  v_dq      integer;
  v_grace   integer := public.config_double('startups', '{insolvency,graceQuarters}', 4)::integer;
  v_plp     jsonb := coalesce(public.config_jsonb('jobs', '{profitLinkedPay}'), '{}'::jsonb);
  v_prev    integer;
  k         text;
  b         record;
begin
  select * into pc from public.player_companies where company_id = p_company and status = 'active' for update;
  select * into q from public.game_quarters where id = p_quarter_id;
  if pc.company_id is null or q.id is null then
    return null;
  end if;
  if exists (select 1 from public.player_company_reports r where r.company_id = p_company and r.game_quarter_id = p_quarter_id) then
    return jsonb_build_object('company_id', p_company, 'skipped', 'already_closed');
  end if;
  select * into c from public.companies where id = p_company;
  v_team := public.player_company_team(p_company);
  v_acc := public.company_cash_account(p_company);
  k := 'pcq:' || p_company::text || ':' || p_quarter_id::text;

  -- the quarter's operating hours (money was booked hourly)
  select count(*) as n,
         coalesce(sum(x.demand_cents), 0)::bigint as demand, coalesce(sum(x.capacity_cents), 0)::bigint as cap,
         coalesce(sum(x.revenue_cents), 0)::bigint as rev, coalesce(sum(x.cogs_cents), 0)::bigint as cogs,
         coalesce(sum(x.fixed_cents), 0)::bigint as fixed, coalesce(sum(x.marketing_cents), 0)::bigint as mk,
         coalesce(sum(x.player_wages_due_cents), 0)::bigint as pdue, coalesce(sum(x.player_wages_paid_cents), 0)::bigint as ppaid,
         coalesce(sum(x.ai_wages_due_cents), 0)::bigint as aidue, coalesce(sum(x.ai_wages_paid_cents), 0)::bigint as aipaid,
         coalesce(sum(x.paid_costs_cents), 0)::bigint as paidcosts, coalesce(sum(x.unpaid_added_cents), 0)::bigint as unpaid,
         coalesce(sum(x.profit_cents), 0)::bigint as profit
    into h
    from public.player_company_hours x where x.company_id = p_company and x.game_quarter_id = q.id;
  v_factor := case when h.pdue + h.aidue <= 0 then 10000
                   else least(10000, (h.ppaid + h.aipaid) * 10000 / (h.pdue + h.aidue))::integer end;

  -- quality towards what the team can do, awareness by word of mouth and marketing (for the next quarter)
  v_target := public.cfg_num(v_su, '{quality,base}', 0.25)
            + (1 - public.cfg_num(v_su, '{quality,base}', 0.25))
              * (greatest(0, (v_team ->> 'team_sector_score')::double precision)
                 / (greatest(0, (v_team ->> 'team_sector_score')::double precision) + public.cfg_num(v_su, '{quality,halfSaturationScore}', 20)));
  v_stage := least(greatest((v_team ->> 'stage')::integer, 0),
                   greatest(jsonb_array_length(coalesce(v_su #> '{stages,awarenessCaps}', '[1]'::jsonb)) - 1, 0));
  v_target := least(1, v_target + public.cfg_num(v_su, '{stages,qualityBonusPerStage}', 0.05) * v_stage);
  -- AI workers do standard work (ADR-069)
  v_target := v_target * (1 - public.cfg_num(v_su, '{aiQualityPenalty}', 0.3)
              * pc.ai_workers::double precision
              / greatest(1, 1 + coalesce((v_team ->> 'employees')::integer, 0) + pc.ai_workers));
  v_quality := least(1, greatest(0, pc.quality + public.cfg_num(v_su, '{quality,adjustPerQuarter}', 0.35) * (v_target - pc.quality)));
  v_mkq := pc.marketing_cents_per_quarter;
  if v_mkq > 0 then
    v_half := greatest(public.cfg_num(v_su, '{awareness,marketingMinHalfSaturationCents}', 50000),
                       pc.potential_annual_cents / 4.0 * public.cfg_num(v_su, '{awareness,marketingHalfSaturationShare}', 0.1));
    v_gain := public.cfg_num(v_su, '{awareness,marketingMaxGain}', 0.12) * v_mkq / (v_mkq + v_half);
  end if;
  v_aw := least(greatest(public.cfg_num(v_su, '{awareness,min}', 0.01),
                         coalesce((v_su #>> array['stages', 'awarenessCaps', v_stage::text])::double precision, 1)),
          greatest(public.cfg_num(v_su, '{awareness,min}', 0.01),
            pc.awareness
            + public.cfg_num(v_su, '{awareness,growthPerQuarter}', 0.3) * pc.awareness * (1 - pc.awareness) * (0.5 + v_quality)
            + v_gain
            - public.cfg_num(v_su, '{awareness,decayPerQuarter}', 0.03) * pc.awareness));

  -- profit bonus (ADR-058): bonusShareOfProfit of the quarter's profit (after wages) by base-wage weight,
  -- at most maxBonusFactor x the base wages of the quarter
  select coalesce(sum(coalesce(sp.base_amount_cents, sp.minutes_paid::bigint * j.salary_cents_per_hour / 60)), 0) into v_bwages
    from public.salary_payouts sp join public.player_jobs j on j.id = sp.player_job_id
   where j.company_id = p_company and sp.period_end > q.starts_at and sp.period_end <= q.ends_at;
  if to_regclass('pg_temp.nexa_bonus') is null then
    create temporary table nexa_bonus (job_id uuid, player_id uuid, bonus bigint) on commit drop;
  end if;
  delete from pg_temp.nexa_bonus;
  if h.profit > 0 then
    select coalesce(sum(x.w), 0) into v_weight
      from (select sum(coalesce(sp.base_amount_cents, sp.minutes_paid::bigint * j.salary_cents_per_hour / 60)) as w
              from public.salary_payouts sp join public.player_jobs j on j.id = sp.player_job_id
             where j.company_id = p_company and j.status = 'active' and sp.period_end > q.starts_at and sp.period_end <= q.ends_at
             group by j.id) x;
    if v_weight > 0 then
      v_pool := floor(h.profit * public.cfg_num(v_plp, '{bonusShareOfProfit}', 0.2))::bigint;
      insert into pg_temp.nexa_bonus (job_id, player_id, bonus)
      select x.id, x.player_id, least(v_pool * x.w / v_weight, floor(x.w * public.cfg_num(v_plp, '{maxBonusFactor}', 1))::bigint)
        from (select j.id, j.player_id, sum(coalesce(sp.base_amount_cents, sp.minutes_paid::bigint * j.salary_cents_per_hour / 60)) as w
                from public.salary_payouts sp join public.player_jobs j on j.id = sp.player_job_id
               where j.company_id = p_company and j.status = 'active' and sp.period_end > q.starts_at and sp.period_end <= q.ends_at
               group by j.id, j.player_id) x;
      delete from pg_temp.nexa_bonus where bonus <= 0;
      select coalesce(sum(bonus), 0) into v_btotal from pg_temp.nexa_bonus;
    end if;
  end if;
  if v_btotal > 0 then
    -- paid only from the cash that is there (scaled down proportionally)
    select greatest(0, a.balance_cents) into v_cash from public.ledger_accounts a where a.id = v_acc;
    for b in select * from pg_temp.nexa_bonus order by job_id loop
      v_b := case when v_cash >= v_btotal then b.bonus else b.bonus * v_cash / v_btotal end;
      if v_b > 0 then
        perform public.lock_player_accounts(b.player_id);
        perform public.ledger_transfer(v_acc, public.ledger_player_account(b.player_id, 'player_cash'), v_b, 'work_bonus',
                                       'Bonus ' || public.game_quarter_label(q.id), 'player_job', b.job_id,
                                       k || ':bonus:' || b.job_id::text, b.player_id);
        perform public.loan_withhold(b.player_id, v_b, k || ':bonus:' || b.job_id::text);
        insert into public.salary_payouts (player_job_id, player_id, pay_day, period_start, period_end, minutes_paid, amount_cents,
                                           bonus_cents, base_amount_cents)
        values (b.job_id, b.player_id, (q.ends_at at time zone 'Europe/Berlin')::date, q.starts_at, q.ends_at, 0, 0, v_b, 0);
        v_bpaid := v_bpaid + v_b;
      end if;
    end loop;
  end if;

  if h.profit > 0 then
    v_xp := public.grant_xp(pc.founder_id, 'company_quarter_profit',
                            public.config_double('progression', '{xpSources,profitableCompanyQuarter,xp}', 500)::integer,
                            'company_quarter:' || p_company::text || ':' || q.id::text, 'company', p_company);
  end if;

  -- distress (ADR-058): open bills at the close count one quarter; new bills this quarter let the AI workers go
  v_ai := case when pc.unpaid_cents > 0 and h.unpaid > 0 then 0 else pc.ai_workers end;
  v_dq := case when pc.unpaid_cents > 0 then pc.distress_quarters + 1 else 0 end;
  update public.player_companies
     set awareness = v_aw, quality = v_quality, quarters_active = quarters_active + 1, last_closed_quarter_id = q.id,
         distress = pc.unpaid_cents > 0, distress_quarters = v_dq, ai_workers = v_ai
   where company_id = p_company;

  select r.pay_factor_bps into v_prev
    from public.player_company_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
   where r.company_id = p_company order by gq.ends_at desc limit 1;
  insert into public.player_company_reports (company_id, game_quarter_id, label, demand_cents, capacity_cents, revenue_cents,
                                             cogs_cents, fixed_cents, ai_worker_cents, marketing_cents, wages_cents,
                                             operating_profit_cents, utilization_bps, paid_costs_cents, unpaid_added_cents,
                                             awareness_bps, quality_bps, team_productivity_bps, team_sector_score,
                                             base_wages_cents, bonus_cents, pay_factor_bps)
  values (p_company, q.id, public.game_quarter_label(q.id), h.demand, h.cap, h.rev, h.cogs, h.fixed, h.aipaid, h.mk, h.ppaid,
          h.profit, round(case when h.cap > 0 then least(1, h.demand::double precision / h.cap) else 1 end * 10000)::integer,
          h.cogs + h.aipaid + h.paidcosts, h.unpaid, round(v_aw * 10000)::integer, round(v_quality * 10000)::integer,
          (v_team ->> 'team_productivity_bps')::integer, (v_team ->> 'team_sector_score')::integer,
          v_bwages, v_bpaid, v_factor);

  -- listed: fair value per share = company value / shares outstanding (ADR-067)
  if c.phase = 'listed' and c.security_id is not null then
    update public.security_sim_state
       set fair_value_e4 = greatest(1, public.company_value_cents(p_company) * 100 / greatest(c.shares_outstanding, 1))
     where security_id = c.security_id;
  end if;

  -- company chat
  perform public.company_system_message(p_company, 'Quartal ' || public.game_quarter_label(q.id) || ': Umsatz '
                                                   || public.format_eur(h.rev) || ', Gewinn ' || public.format_eur(h.profit) || '.');
  if v_bpaid > 0 then
    perform public.company_system_message(p_company, 'Bonus für das Team: ' || public.format_eur(v_bpaid) || '.');
  end if;
  if v_factor <> coalesce(v_prev, 10000) then
    perform public.company_system_message(p_company, 'Lohnfaktor im Quartal: ' || floor(v_factor / 100.0) || ' %.');
  end if;
  -- insolvency after graceQuarters closes with open bills (isInsolvent)
  if v_dq >= v_grace then
    perform public.company_dissolve(p_company, 'insolvent');
  elsif v_dq > 0 then
    perform public.company_system_message(p_company, 'Achtung: offene Rechnungen. Noch ' || (v_grace - v_dq)
                                                     || case when v_grace - v_dq = 1 then ' Quartal' else ' Quartale' end
                                                     || ' bis zur Insolvenz.');
  end if;

  return jsonb_build_object('company_id', p_company, 'quarter_id', q.id, 'hours', h.n, 'revenue_cents', h.rev,
                            'operating_profit_cents', h.profit, 'unpaid_added_cents', h.unpaid, 'xp', v_xp,
                            'base_wages_cents', v_bwages, 'bonus_cents', v_bpaid, 'pay_factor_bps', v_factor,
                            'distress_quarters', v_dq, 'dissolved', v_dq >= v_grace);
end;
$$;

-- ---------------------------------------------------------------------------
-- E. Due hours and quarters of all player companies (run_due_jobs)
-- ---------------------------------------------------------------------------
-- Per company, oldest first: operating hours up to the last full hour (at most
-- 48 per run), each quarter as soon as its hours are closed. Hours stop at the
-- end of a quarter that is not reported yet, so a quarter's awareness and
-- quality always apply to the next quarter's hours (matters only when catching up).
create or replace function public.player_companies_run_due()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now    timestamptz := public.game_now();
  v_limit  timestamptz := date_trunc('hour', public.game_now());
  r        record;
  q        record;
  v_at     timestamptz;
  v_last   timestamptz;
  v_hours  integer := 0;
  v_quart  integer := 0;
  v_k      integer;
  v_kq     integer;
  v_moved  boolean;
begin
  for r in
    select pc.company_id, c.founded_at
      from public.player_companies pc join public.companies c on c.id = pc.company_id
     where pc.status = 'active'
     order by pc.company_id
  loop
    v_k := 0;
    v_kq := 0;
    loop
      v_moved := false;
      -- quarters whose hours are all closed
      for q in
        select gq.id from public.game_quarters gq, public.player_companies pc
         where pc.company_id = r.company_id and pc.status = 'active'
           and gq.status = 'closed' and gq.ends_at <= pc.last_hour_at
           and gq.ends_at > coalesce((select x.ends_at from public.game_quarters x where x.id = pc.last_closed_quarter_id), r.founded_at)
           and not exists (select 1 from public.player_company_reports rp where rp.company_id = r.company_id and rp.game_quarter_id = gq.id)
         order by gq.ends_at limit greatest(0, 8 - v_kq)
      loop
        exit when not exists (select 1 from public.player_companies x where x.company_id = r.company_id and x.status = 'active');
        if (public.player_company_close_quarter(r.company_id, q.id) ->> 'skipped') is null then
          v_quart := v_quart + 1;
          v_kq := v_kq + 1;
          v_moved := true;
        end if;
      end loop;
      -- hours up to the next unreported quarter end
      loop
        select pc.last_hour_at,
               coalesce((select x.ends_at from public.game_quarters x where x.id = pc.last_closed_quarter_id), r.founded_at)
          into v_at, v_last
          from public.player_companies pc where pc.company_id = r.company_id and pc.status = 'active';
        exit when v_at is null or v_at + interval '1 hour' > v_limit or v_k >= 48;
        exit when exists (select 1 from public.game_quarters gq
                           where gq.ends_at <= v_at and gq.ends_at > v_last
                             and not exists (select 1 from public.player_company_reports rp
                                              where rp.company_id = r.company_id and rp.game_quarter_id = gq.id));
        perform public.player_company_close_hour(r.company_id, v_at);
        v_hours := v_hours + 1;
        v_k := v_k + 1;
        v_moved := true;
      end loop;
      exit when not v_moved or v_k >= 48 or v_kq >= 8;
    end loop;
  end loop;
  -- keep about one week of hours
  delete from public.player_company_hours where hour_start < v_now - interval '7 days';
  return jsonb_build_object('hours', v_hours, 'quarters', v_quart);
end;
$$;
comment on function public.player_companies_run_due() is
  'run_due_jobs: closes due operating hours (max. 48 per company and run) and quarters of all active player companies.';

-- as before (M3c): number of quarters closed; now with the due hours first
create or replace function public.player_companies_close_due()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
begin
  return (public.player_companies_run_due() ->> 'quarters')::integer;
end;
$$;

create or replace function public.run_due_jobs()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now      timestamptz;
  v_result   jsonb := '{}'::jsonb;
  v_closed   jsonb := '[]'::jsonb;
  v_latest   bigint;
  q          record;
  v_run      bigint;
begin
  -- waits for a running tick (ticks only try the lock and skip)
  perform pg_advisory_xact_lock(7311001);
  v_now := public.game_now();
  perform public.ensure_game_quarters(3);

  if not exists (select 1 from public.candles limit 1) or not public.money_genesis_done()
     or not exists (select 1 from public.rich_tycoons) then
    v_result := v_result || jsonb_build_object('bootstrap', public.market_bootstrap());
  end if;

  -- first run on a database: older quarters are skipped, only the latest ended one is closed
  if not exists (select 1 from public.job_runs j where j.job_name = 'quarter_close') then
    select gq.id into v_latest from public.game_quarters gq
     where gq.ends_at <= v_now and gq.status <> 'closed' order by gq.ends_at desc limit 1;
    for q in select gq.id from public.game_quarters gq
              where gq.ends_at <= v_now and gq.status <> 'closed' and gq.id <> coalesce(v_latest, -1)
    loop
      update public.game_quarters set status = 'closed', closed_at = now() where id = q.id;
      insert into public.job_runs (job_name, run_key, status, finished_at, details)
      values ('quarter_close', q.id::text, 'succeeded', now(), '{"skipped": "before_first_run"}'::jsonb)
      on conflict do nothing;
    end loop;
  end if;

  for q in select gq.id from public.game_quarters gq
            where gq.ends_at <= v_now and gq.status <> 'closed'
            order by gq.ends_at limit 8
  loop
    v_closed := v_closed || public.close_game_quarter(q.id);
  end loop;
  v_result := v_result || jsonb_build_object('quarters', v_closed);
  -- player companies: operating hours (ADR-072), then every closed quarter since their founding (ADR-057)
  v_result := v_result || jsonb_build_object('player_companies', public.player_companies_run_due());

  -- bonds that matured between quarter closes (or after a downtime)
  if exists (select 1 from public.bonds bd join public.securities s on s.id = bd.security_id
              where s.status = 'listed' and bd.matures_at <= v_now) then
    v_result := v_result || jsonb_build_object('bonds_redeemed', public.redeem_matured_bonds(v_now));
  end if;
  v_result := v_result || jsonb_build_object('bonds_issued', public.ensure_bond_series());

  -- jobs: AI postings of the running quarter, wages of AI-company jobs in whole hours
  v_result := v_result || jsonb_build_object('quit_notices', public.process_quit_notices(null));
  v_result := v_result || jsonb_build_object('share_offers', public.close_due_offers(null));
  v_result := v_result || jsonb_build_object('job_postings', public.refresh_ai_job_postings(),
                                             'salaries_paid', public.accrue_salaries(null));

  -- rich list snapshot every richList.snapshotMinutes (rank news, 24 h changes, state missions)
  v_result := v_result || jsonb_build_object('rich_list', public.rich_list_snapshot(false));

  -- daily maintenance (first run per UTC day)
  insert into public.job_runs (job_name, run_key) values ('maintenance', to_char(now() at time zone 'UTC', 'YYYY-MM-DD'))
  on conflict (job_name, run_key) do nothing
  returning id into v_run;
  if v_run is not null then
    v_result := v_result || jsonb_build_object('maintenance', public.run_maintenance());
    -- price_ticks: keep about one day (candles hold the history), cron log: one day
    perform public.maintain_price_tick_partitions(3, 1);
    if to_regclass('cron.job_run_details') is not null then
      begin
        execute 'delete from cron.job_run_details where end_time < now() - interval ''1 day''';
      exception when others then
        raise warning 'NEXA: could not prune cron.job_run_details: %', sqlerrm;
      end;
    end if;
    delete from public.job_runs j where j.job_name = 'maintenance' and j.started_at < now() - interval '30 days';
    update public.job_runs set status = 'succeeded', finished_at = now() where id = v_run;
  end if;
  return v_result;
end;
$$;

-- ---------------------------------------------------------------------------
-- F. COMPANY: live figures and the last 24 hours
-- ---------------------------------------------------------------------------
create or replace function public.company_live_json(p_company uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  pc        public.player_companies;
  v_day     timestamptz := ((public.game_now() at time zone 'Europe/Berlin')::date)::timestamp at time zone 'Europe/Berlin';
  v_qid     bigint := (public.current_game_quarter()).id;
  v_rev     bigint;
  v_profit  bigint;
  v_trev    bigint;
  v_tprofit bigint;
  v_qrev    bigint;
  v_qprofit bigint;
begin
  select * into pc from public.player_companies where company_id = p_company;
  select h.revenue_cents, h.profit_cents into v_rev, v_profit
    from public.player_company_hours h where h.company_id = p_company order by h.hour_start desc limit 1;
  select coalesce(sum(h.revenue_cents), 0), coalesce(sum(h.profit_cents), 0) into v_trev, v_tprofit
    from public.player_company_hours h
   where h.company_id = p_company and h.hour_start >= v_day
     and h.hour_start < ((v_day at time zone 'Europe/Berlin') + interval '1 day') at time zone 'Europe/Berlin';
  select coalesce(sum(h.revenue_cents), 0), coalesce(sum(h.profit_cents), 0) into v_qrev, v_qprofit
    from public.player_company_hours h where h.company_id = p_company and h.game_quarter_id = v_qid;
  return jsonb_build_object(
    'last_hour_at', pc.last_hour_at,
    'revenue_per_hour_cents', coalesce(v_rev, 0),
    'profit_per_hour_cents', coalesce(v_profit, 0),
    'pay_factor_bps', pc.pay_factor_bps,
    'today_revenue_cents', v_trev,
    'today_profit_cents', v_tprofit,
    'quarter_revenue_cents', v_qrev,
    'quarter_profit_cents', v_qprofit);
end;
$$;
comment on function public.company_live_json(uuid) is
  'COMPANY.live: last closed hour, Berlin day and running quarter of a player company (ADR-072).';

create or replace function public.company_hours_json(p_company uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object('hour_start', x.hour_start, 'revenue_cents', x.revenue_cents,
                                               'profit_cents', x.profit_cents) order by x.hour_start), '[]'::jsonb)
    from (select h.hour_start, h.revenue_cents, h.profit_cents from public.player_company_hours h
           where h.company_id = p_company order by h.hour_start desc limit 24) x;
$$;
comment on function public.company_hours_json(uuid) is 'COMPANY.hours: the last 24 closed operating hours, oldest first.';

-- company_state as in M3h plus live, hours and ai_wage_cents_per_hour
create or replace function public.company_state(p_company uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  pc       public.player_companies;
  c        public.companies;
  v_team   jsonb;
  v_tier   jsonb;
  v_sb     jsonb;
  v_level  integer;
  v_cash   bigint;
  v_spread double precision;
  v_last   jsonb;
  v_hist   jsonb;
  v_cost   bigint;
begin
  select * into pc from public.player_companies where company_id = p_company;
  if pc.company_id is null then
    return null;
  end if;
  select * into c from public.companies where id = p_company;
  v_team := public.player_company_team(p_company);
  v_tier := public.company_tier_cfg(pc.tier);
  v_sb := public.company_tier_cfg('small_business');
  select p.level into v_level from public.profiles p where p.id = pc.founder_id;
  v_cash := coalesce((select a.balance_cents from public.ledger_accounts a where a.owner_company_id = p_company and a.kind = 'company_cash'), 0);
  v_spread := public.config_double('startups', '{estimate,initialSpread}', 2.3)
            * power(public.config_double('startups', '{estimate,decayPerQuarter}', 0.85), pc.quarters_active);
  select jsonb_build_object(
           'label', r.label, 'demand_cents', r.demand_cents, 'capacity_cents', r.capacity_cents,
           'revenue_cents', r.revenue_cents, 'cogs_cents', r.cogs_cents, 'fixed_cents', r.fixed_cents,
           'ai_worker_cents', r.ai_worker_cents, 'marketing_cents', r.marketing_cents, 'wages_cents', r.wages_cents,
           'operating_profit_cents', r.operating_profit_cents, 'utilization_bps', r.utilization_bps,
           'bonus_cents', r.bonus_cents)
    into v_last
    from public.player_company_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
   where r.company_id = p_company order by gq.ends_at desc limit 1;
  select coalesce(jsonb_agg(jsonb_build_object('label', h.label, 'revenue_cents', h.revenue_cents,
                                               'profit_cents', h.operating_profit_cents) order by h.ends_at), '[]'::jsonb)
    into v_hist
    from (select r.label, r.revenue_cents, r.operating_profit_cents, gq.ends_at
            from public.player_company_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
           where r.company_id = p_company order by gq.ends_at desc limit 12) h;
  v_cost := public.company_upgrade_cost(pc.tier);
  return jsonb_build_object(
    'id', c.id,
    'name', c.name,
    'idea', pc.idea,
    'sector', c.sector_key,
    'color', c.brand_color,
    'logo', public.company_logo(p_company),
    'logo_hidden', pc.logo_hidden,
    'founder_has_job', exists (select 1 from public.player_jobs x where x.player_id = pc.founder_id and x.status = 'active'),
    'full_time_from', public.config_double('startups', '{fullTimeFromEmployees}', 5)::integer,
    'training_from', public.config_double('startups', '{training,fromEmployees}', 5)::integer,
    'headcount', public.company_headcount(p_company),
    'tier', pc.tier,
    'founded_at', c.founded_at,
    'cash_cents', v_cash,
    'value_cents', public.company_value_cents(p_company),
    'unpaid_cents', pc.unpaid_cents,
    'distress', pc.distress,
    'distress_quarters', pc.distress_quarters,
    'grace_quarters', public.config_double('startups', '{insolvency,graceQuarters}', 4)::integer,
    'pay_factor_bps', pc.pay_factor_bps,
    'product_key', public.company_product(p_company) ->> 'key',
    'stage', (v_team ->> 'stage')::integer,
    'stages', public.company_stages_json(p_company),
    'awareness_bps', round(pc.awareness * 10000)::integer,
    'quality_bps', round(pc.quality * 10000)::integer,
    'quarters_active', pc.quarters_active,
    'estimate_low_cents', round(pc.potential_annual_cents
                                * exp(-v_spread * (0.3 + 0.7 * public.uniform_from_text(pc.company_id::text || ':' || pc.quarters_active || ':low'))))::bigint,
    'estimate_high_cents', round(pc.potential_annual_cents
                                 * exp(v_spread * (0.3 + 0.7 * public.uniform_from_text(pc.company_id::text || ':' || pc.quarters_active || ':high'))))::bigint,
    'marketing_cents_per_quarter', pc.marketing_cents_per_quarter,
    'ai_workers', pc.ai_workers,
    'ai_worker_cost_cents', public.config_bigint('startups', '{aiWorkerCostCentsPerQuarter}', 72000),
    'ai_wage_cents_per_hour', public.config_bigint('startups', '{aiWorkerWageCentsPerHour}', 12000),
    'ai_worker_skills', to_jsonb(pc.ai_worker_skills),
    'max_employees', (v_tier ->> 'maxEmployees')::integer,
    'employees', (v_team ->> 'employees')::integer,
    'open_postings', (select count(*) from public.job_postings jp where jp.company_id = p_company and jp.status = 'open')::integer,
    'pending_applications', (select count(*) from public.job_applications a join public.job_postings jp on jp.id = a.posting_id
                              where jp.company_id = p_company and a.status = 'pending')::integer,
    'founder_productivity_bps', (v_team ->> 'founder_productivity_bps')::integer,
    'team_productivity_bps', (v_team ->> 'team_productivity_bps')::integer,
    'capacity_cents', (v_team ->> 'capacity_cents')::bigint,
    'next_quarter_at', coalesce((public.current_game_quarter()).ends_at, public.game_now()),
    'can_upgrade', public.company_next_tier(pc.tier) is not null
                   and coalesce(v_level, 1) >= (public.company_tier_cfg(public.company_next_tier(pc.tier)) ->> 'minLevel')::integer,
    'listing', public.company_listing_json(p_company, pc.founder_id),
    'can_go_public', c.phase = 'private' and public.company_open_offer(p_company) is null
                     and coalesce(public.config_jsonb('startups', '{ipo,fromTiers}'), '["small_business", "gmbh"]'::jsonb) ? pc.tier
                     and coalesce(v_level, 1) >= public.config_double('startups', '{ipo,minLevel}', 12),
    'can_capital_increase', c.phase = 'listed' and public.company_open_offer(p_company) is null,
    'upgrade_cost_cents', v_cost,
    'last_quarter', v_last,
    'history', v_hist,
    'live', public.company_live_json(p_company),
    'hours', public.company_hours_json(p_company));
end;
$$;

-- ---------------------------------------------------------------------------
-- G. Company ranking (ADR-074)
-- ---------------------------------------------------------------------------
-- Player companies by value: company_value_cents, listed ones at market value
-- (shares x last price, as the founder's shares count on the rich list).
-- Scope 'all' adds the listed AI companies at market value.
create or replace function public.get_company_ranking(p_scope text default 'players', p_limit integer default 100)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_scope  text := coalesce(p_scope, 'players');
  v_limit  integer := least(greatest(coalesce(p_limit, 100), 1), 500);
  v_out    jsonb;
begin
  v_player := public.require_player();
  if v_scope not in ('players', 'all') then
    perform public.api_error('invalid_argument');
  end if;

  with lst as materialized (
    select c.id, 'player'::text as kind, c.name, coalesce(c.brand_color, '#808080') as color,
           public.company_logo(c.id) as logo, c.ticker, c.sector_key, pc.tier, pr.nickname as founder,
           case when c.phase = 'listed' and qt.last_price_e4 is not null
                then public.div_round_half_even(c.shares_outstanding::numeric * qt.last_price_e4, 100)::bigint
                else public.company_value_cents(c.id) end as value_cents,
           (select r.revenue_cents from public.player_company_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
             where r.company_id = c.id order by gq.ends_at desc limit 1) as revenue_cents,
           1 + pc.ai_workers + (select count(*) from public.player_jobs j where j.company_id = c.id and j.status = 'active')::integer
             as team_size,
           pc.founder_id = v_player as is_mine
      from public.player_companies pc
      join public.companies c on c.id = pc.company_id
      left join public.profiles pr on pr.id = pc.founder_id
      left join public.security_quotes qt on qt.security_id = c.security_id
     where pc.status = 'active'
    union all
    select c.id, 'ai', c.name, coalesce(c.brand_color, '#808080'), null::jsonb, c.ticker, c.sector_key, null::text, null::text,
           public.div_round_half_even(c.shares_outstanding::numeric * qt.last_price_e4, 100)::bigint,
           null::bigint, null::integer, false
      from public.companies c
      join public.securities s on s.id = c.security_id and s.status = 'listed' and s.kind = 'stock'
      join public.security_quotes qt on qt.security_id = s.id
     where v_scope = 'all' and c.is_ai
  ), ranked as materialized (
    select l.*, (row_number() over (order by l.value_cents desc, l.name, l.id))::integer as rnk from lst l
  )
  select jsonb_build_object(
           'server_time', public.game_now(),
           'total', (select count(*) from ranked)::integer,
           'entries', coalesce((select jsonb_agg(jsonb_build_object(
                                  'rank', x.rnk, 'company_id', x.id, 'kind', x.kind, 'name', x.name, 'color', x.color,
                                  'logo', x.logo, 'ticker', x.ticker, 'sector', x.sector_key, 'tier', x.tier,
                                  'founder', x.founder, 'value_cents', x.value_cents, 'revenue_cents', x.revenue_cents,
                                  'team_size', x.team_size, 'is_mine', x.is_mine) order by x.rnk)
                                  from ranked x where x.rnk <= v_limit), '[]'::jsonb),
           'mine', (select jsonb_build_object('rank', x.rnk, 'value_cents', x.value_cents)
                      from ranked x where x.is_mine and x.kind = 'player' limit 1))
    into v_out;
  return v_out;
end;
$$;
comment on function public.get_company_ranking(text, integer) is
  'RPC: top companies (ADR-074); players: active player companies by value, all: plus listed AI companies by market value.';

-- ---------------------------------------------------------------------------
-- H. Logo once, forbidden symbols blocked (ADR-076)
-- ---------------------------------------------------------------------------
-- Port of hasForbiddenSymbol (src/lib/sim/logo.ts): three templates in all
-- rotations and mirror images, scales 1..3 while the scaled template fits,
-- matched in the whole-drawing mask and in each colour's mask, at most one wrong
-- template cell. At scale k a cell is right iff its k x k block is fully set ('x')
-- or fully empty ('.'). Block counts come from prefix sums.
create or replace function public.logo_has_forbidden_symbol(p_grid jsonb)
returns boolean
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_templates jsonb := '[["x.xxx", "x.x..", "xxxxx", "..x.x", "xxx.x"],
                         ["x..xxxx", "x..x...", "x..x...", "xxxxxxx", "...x..x", "...x..x", "xxxx..x"],
                         ["x...xxxxx", "x...x....", "x...x....", "x...x....", "xxxxxxxxx", "....x...x", "....x...x", "....x...x", "xxxxx...x"]]';
  v_rows  text[];
  v_size  integer;
  v_w1    integer;
  v_pats  text[] := '{}';        -- variants, rows joined with '/'
  v_cur   text[];
  v_rot   text[];
  v_key   text;
  v_chars text[];
  v_ch    text;
  v_ps    integer[];
  v_pat   text[];
  v_h     integer;
  v_w     integer;
  v_k     integer;
  v_set   integer;
  v_err   integer;
  v_ok    boolean;
  t       jsonb;
  i       integer;
  x       integer;
  y       integer;
  ox      integer;
  oy      integer;
  tx      integer;
  ty      integer;
  y0      integer;
  x0      integer;
begin
  if p_grid is null or jsonb_typeof(p_grid) <> 'array' then
    return false;
  end if;
  select array_agg(coalesce(e #>> '{}', '') order by o) into v_rows from jsonb_array_elements(p_grid) with ordinality a(e, o);
  v_size := coalesce(array_length(v_rows, 1), 0);
  if v_size = 0 then
    return false;
  end if;
  v_w1 := v_size + 1;

  -- variants: four rotations, each with its mirror image (duplicates dropped)
  for t in select value from jsonb_array_elements(v_templates) loop
    select array_agg(r order by o) into v_cur from jsonb_array_elements_text(t) with ordinality a(r, o);
    for i in 1..4 loop
      v_key := array_to_string(v_cur, '/');
      if not (v_key = any (v_pats)) then
        v_pats := v_pats || v_key;
      end if;
      v_key := (select string_agg(reverse(r), '/' order by o) from unnest(v_cur) with ordinality a(r, o));
      if not (v_key = any (v_pats)) then
        v_pats := v_pats || v_key;
      end if;
      -- rotate: new row x = column x read from the bottom up
      v_rot := '{}';
      for x in 1..char_length(v_cur[1]) loop
        v_rot := v_rot || (select string_agg(substr(v_cur[yy], x, 1), '' order by yy desc)
                             from generate_series(1, array_length(v_cur, 1)) yy);
      end loop;
      v_cur := v_rot;
    end loop;
  end loop;

  -- masks: the whole drawing ('*'), then every colour used
  v_chars := array['*'] || coalesce((select array_agg(distinct ch order by ch)
                                       from unnest(v_rows) r, regexp_split_to_table(r, '') ch where ch <> '.'), '{}');
  foreach v_ch in array v_chars loop
    -- prefix sums: v_ps[y * (size + 1) + x + 1] = set cells in rows < y and columns < x
    v_ps := array_fill(0, array[v_w1 * v_w1]);
    for y in 1..v_size loop
      for x in 1..v_size loop
        v_ps[y * v_w1 + x + 1] := v_ps[(y - 1) * v_w1 + x + 1] + v_ps[y * v_w1 + x] - v_ps[(y - 1) * v_w1 + x]
          + case when (v_ch = '*' and substr(v_rows[y], x, 1) not in ('.', ''))
                      or (v_ch <> '*' and substr(v_rows[y], x, 1) = v_ch) then 1 else 0 end;
      end loop;
    end loop;
    foreach v_key in array v_pats loop
      v_pat := string_to_array(v_key, '/');
      v_h := array_length(v_pat, 1);
      v_w := char_length(v_pat[1]);
      v_k := 1;
      while v_k <= 3 and v_k * greatest(v_w, v_h) <= v_size loop
        for oy in 0..v_size - v_h * v_k loop
          for ox in 0..v_size - v_w * v_k loop
            v_err := 0;
            v_ok := true;
            <<cells>>
            for ty in 0..v_h - 1 loop
              for tx in 0..v_w - 1 loop
                y0 := oy + ty * v_k;
                x0 := ox + tx * v_k;
                v_set := v_ps[(y0 + v_k) * v_w1 + x0 + v_k + 1] - v_ps[y0 * v_w1 + x0 + v_k + 1]
                       - v_ps[(y0 + v_k) * v_w1 + x0 + 1] + v_ps[y0 * v_w1 + x0 + 1];
                if (substr(v_pat[ty + 1], tx + 1, 1) = 'x' and v_set <> v_k * v_k)
                   or (substr(v_pat[ty + 1], tx + 1, 1) <> 'x' and v_set <> 0) then
                  v_err := v_err + 1;
                  if v_err > 1 then
                    v_ok := false;
                    exit cells;
                  end if;
                end if;
              end loop;
            end loop;
            if v_ok then
              return true;
            end if;
          end loop;
        end loop;
        v_k := v_k + 1;
      end loop;
    end loop;
  end loop;
  return false;
end;
$$;
comment on function public.logo_has_forbidden_symbol(jsonb) is
  'True if a logo grid shows a forbidden symbol (port of hasForbiddenSymbol in src/lib/sim/logo.ts, ADR-076).';

-- set_company_logo as in M3f: once (a logo hidden by reports may be replaced), no forbidden symbols
-- Error keys (M3i): logo_locked NX064, logo_forbidden NX065.
create or replace function public.set_company_logo(p_request_id uuid, p_logo jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
  pc        public.player_companies;
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null or not public.logo_valid(p_logo) then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'set_company_logo');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into pc from public.player_companies where company_id = v_company for update;
  if pc.logo is not null and not pc.logo_hidden then
    raise exception using errcode = 'NX064', message = 'logo_locked';
  end if;
  if public.logo_has_forbidden_symbol(p_logo -> 'grid') then
    raise exception using errcode = 'NX065', message = 'logo_forbidden';
  end if;
  update public.player_companies
     set logo = jsonb_build_object('palette', p_logo -> 'palette', 'grid', p_logo -> 'grid'),
         logo_version = logo_version + 1, logo_hidden = false
   where company_id = v_company;
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_company)));
end;
$$;

-- ---------------------------------------------------------------------------
-- I. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.job_payable_minutes(uuid, timestamptz)', 'public.accrue_salaries(timestamptz)',
    'public.player_company_close_hour(uuid, timestamptz)', 'public.player_company_close_quarter(uuid, bigint)',
    'public.player_companies_run_due()', 'public.player_companies_close_due()', 'public.run_due_jobs()', 'public.company_live_json(uuid)',
    'public.company_hours_json(uuid)', 'public.company_state(uuid)', 'public.get_company_ranking(text, integer)',
    'public.logo_has_forbidden_symbol(jsonb)', 'public.set_company_logo(uuid, jsonb)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  execute 'grant execute on function public.get_company_ranking(text, integer) to authenticated';
  execute 'grant execute on function public.set_company_logo(uuid, jsonb) to authenticated';
end;
$$;

-- ===== supabase/updates/20261121000100_m3j_banner.sql =====
-- ===== idempotent copy of migrations/20261121000100_m3j_banner.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · M3j · 0100 · Company banner (ADR-078)
-- =============================================================================
-- A pixel banner above the company page: like the logo, but startups.banner.width
-- × startups.banner.height cells and redrawable at any time (no lock, no reports).
-- Mirrors isValidBanner and hasForbiddenSymbol in src/lib/sim/logo.ts; the forbidden
-- symbol check now works on any width × height (logos stay 16 × 16).
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. Column
-- ---------------------------------------------------------------------------
alter table public.player_companies
  add column if not exists banner jsonb check (banner is null or pg_column_size(banner) < 8192);
comment on column public.player_companies.banner is
  'Pixel banner {palette: [#rrggbb], grid: [height x width chars]} above the company page (ADR-078); null = none.';
grant select (banner) on public.player_companies to authenticated;

-- ---------------------------------------------------------------------------
-- B. Forbidden symbols on width × height grids
-- ---------------------------------------------------------------------------
-- Port of hasForbiddenSymbol (src/lib/sim/logo.ts): three templates in all
-- rotations and mirror images, scales 1..3 while the scaled template fits in both
-- dimensions, matched in the whole-drawing mask and in each colour's mask, at most
-- one wrong template cell. Width = length of the first row, height = row count.
-- At scale k a cell is right iff its k x k block is fully set ('x') or fully
-- empty ('.'). Block counts come from prefix sums.
create or replace function public.logo_has_forbidden_symbol(p_grid jsonb)
returns boolean
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_templates jsonb := '[["x.xxx", "x.x..", "xxxxx", "..x.x", "xxx.x"],
                         ["x..xxxx", "x..x...", "x..x...", "xxxxxxx", "...x..x", "...x..x", "xxxx..x"],
                         ["x...xxxxx", "x...x....", "x...x....", "x...x....", "xxxxxxxxx", "....x...x", "....x...x", "....x...x", "xxxxx...x"]]';
  v_rows  text[];
  v_gh    integer;               -- grid height (rows)
  v_gw    integer;               -- grid width (chars of the first row)
  v_w1    integer;
  v_pats  text[] := '{}';        -- variants, rows joined with '/'
  v_cur   text[];
  v_rot   text[];
  v_key   text;
  v_chars text[];
  v_ch    text;
  v_ps    integer[];
  v_pat   text[];
  v_h     integer;
  v_w     integer;
  v_k     integer;
  v_set   integer;
  v_err   integer;
  v_ok    boolean;
  t       jsonb;
  i       integer;
  x       integer;
  y       integer;
  ox      integer;
  oy      integer;
  tx      integer;
  ty      integer;
  y0      integer;
  x0      integer;
begin
  if p_grid is null or jsonb_typeof(p_grid) <> 'array' then
    return false;
  end if;
  select array_agg(coalesce(e #>> '{}', '') order by o) into v_rows from jsonb_array_elements(p_grid) with ordinality a(e, o);
  v_gh := coalesce(array_length(v_rows, 1), 0);
  if v_gh = 0 then
    return false;
  end if;
  v_gw := char_length(v_rows[1]);
  if v_gw = 0 then
    return false;
  end if;
  v_w1 := v_gw + 1;

  -- variants: four rotations, each with its mirror image (duplicates dropped)
  for t in select value from jsonb_array_elements(v_templates) loop
    select array_agg(r order by o) into v_cur from jsonb_array_elements_text(t) with ordinality a(r, o);
    for i in 1..4 loop
      v_key := array_to_string(v_cur, '/');
      if not (v_key = any (v_pats)) then
        v_pats := v_pats || v_key;
      end if;
      v_key := (select string_agg(reverse(r), '/' order by o) from unnest(v_cur) with ordinality a(r, o));
      if not (v_key = any (v_pats)) then
        v_pats := v_pats || v_key;
      end if;
      -- rotate: new row x = column x read from the bottom up
      v_rot := '{}';
      for x in 1..char_length(v_cur[1]) loop
        v_rot := v_rot || (select string_agg(substr(v_cur[yy], x, 1), '' order by yy desc)
                             from generate_series(1, array_length(v_cur, 1)) yy);
      end loop;
      v_cur := v_rot;
    end loop;
  end loop;

  -- masks: the whole drawing ('*'), then every colour used
  v_chars := array['*'] || coalesce((select array_agg(distinct ch order by ch)
                                       from unnest(v_rows) r, regexp_split_to_table(r, '') ch where ch <> '.'), '{}');
  foreach v_ch in array v_chars loop
    -- prefix sums: v_ps[y * (width + 1) + x + 1] = set cells in rows < y and columns < x
    v_ps := array_fill(0, array[(v_gh + 1) * v_w1]);
    for y in 1..v_gh loop
      for x in 1..v_gw loop
        v_ps[y * v_w1 + x + 1] := v_ps[(y - 1) * v_w1 + x + 1] + v_ps[y * v_w1 + x] - v_ps[(y - 1) * v_w1 + x]
          + case when (v_ch = '*' and substr(v_rows[y], x, 1) not in ('.', ''))
                      or (v_ch <> '*' and substr(v_rows[y], x, 1) = v_ch) then 1 else 0 end;
      end loop;
    end loop;
    foreach v_key in array v_pats loop
      v_pat := string_to_array(v_key, '/');
      v_h := array_length(v_pat, 1);
      v_w := char_length(v_pat[1]);
      v_k := 1;
      while v_k <= 3 and v_k * v_w <= v_gw and v_k * v_h <= v_gh loop
        for oy in 0..v_gh - v_h * v_k loop
          for ox in 0..v_gw - v_w * v_k loop
            v_err := 0;
            v_ok := true;
            <<cells>>
            for ty in 0..v_h - 1 loop
              for tx in 0..v_w - 1 loop
                y0 := oy + ty * v_k;
                x0 := ox + tx * v_k;
                v_set := v_ps[(y0 + v_k) * v_w1 + x0 + v_k + 1] - v_ps[y0 * v_w1 + x0 + v_k + 1]
                       - v_ps[(y0 + v_k) * v_w1 + x0 + 1] + v_ps[y0 * v_w1 + x0 + 1];
                if (substr(v_pat[ty + 1], tx + 1, 1) = 'x' and v_set <> v_k * v_k)
                   or (substr(v_pat[ty + 1], tx + 1, 1) <> 'x' and v_set <> 0) then
                  v_err := v_err + 1;
                  if v_err > 1 then
                    v_ok := false;
                    exit cells;
                  end if;
                end if;
              end loop;
            end loop;
            if v_ok then
              return true;
            end if;
          end loop;
        end loop;
        v_k := v_k + 1;
      end loop;
    end loop;
  end loop;
  return false;
end;
$$;
comment on function public.logo_has_forbidden_symbol(jsonb) is
  'True if a logo or banner grid (any width x height) shows a forbidden symbol (port of hasForbiddenSymbol in src/lib/sim/logo.ts, ADR-076, ADR-078).';

-- ---------------------------------------------------------------------------
-- C. Banner validation and RPC
-- ---------------------------------------------------------------------------
-- isValidBanner: palette 1..banner.maxColors lowercase #rrggbb, banner.height rows of
-- banner.width chars from '.' and the palette indices (no minimum of pixels)
create or replace function public.banner_valid(p_banner jsonb)
returns boolean
language plpgsql
stable
set search_path = ''
as $$
declare
  v_width  integer := public.config_double('startups', '{banner,width}', 48)::integer;
  v_height integer := public.config_double('startups', '{banner,height}', 12)::integer;
  v_max    integer := public.config_double('startups', '{banner,maxColors}', 6)::integer;
  v_n      integer;
  v_re     text;
begin
  if p_banner is null or jsonb_typeof(p_banner) <> 'object'
     or jsonb_typeof(p_banner -> 'palette') is distinct from 'array' or jsonb_typeof(p_banner -> 'grid') is distinct from 'array' then
    return false;
  end if;
  v_n := jsonb_array_length(p_banner -> 'palette');
  if v_n < 1 or v_n > v_max
     or exists (select 1 from jsonb_array_elements(p_banner -> 'palette') c
                 where jsonb_typeof(c) <> 'string' or (c #>> '{}') !~ '^#[0-9a-f]{6}$') then
    return false;
  end if;
  if jsonb_array_length(p_banner -> 'grid') <> v_height then
    return false;
  end if;
  v_re := '^[.0-' || (v_n - 1) || ']{' || v_width || '}$';
  return not exists (select 1 from jsonb_array_elements(p_banner -> 'grid') r
                      where jsonb_typeof(r) <> 'string' or (r #>> '{}') !~ v_re);
end;
$$;
comment on function public.banner_valid(jsonb) is 'Port of isValidBanner (src/lib/sim/logo.ts, ADR-078).';

-- Founder only; may be redrawn any time; null (SQL or JSON) removes the banner.
create or replace function public.set_company_banner(p_request_id uuid, p_banner jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
  v_remove  boolean := p_banner is null or jsonb_typeof(p_banner) = 'null';
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null or (not v_remove and not public.banner_valid(p_banner)) then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'set_company_banner');
  if v_replay is not null then
    return v_replay;
  end if;
  if not v_remove and public.logo_has_forbidden_symbol(p_banner -> 'grid') then
    raise exception using errcode = 'NX065', message = 'logo_forbidden';
  end if;
  update public.player_companies
     set banner = case when v_remove then null
                       else jsonb_build_object('palette', p_banner -> 'palette', 'grid', p_banner -> 'grid') end
   where company_id = v_company;
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_company)));
end;
$$;
comment on function public.set_company_banner(uuid, jsonb) is
  'RPC: set or remove (null) the company banner (ADR-078); founder only, no lock; errors invalid_argument, logo_forbidden.';

-- ---------------------------------------------------------------------------
-- D. COMPANY with banner
-- ---------------------------------------------------------------------------
-- company_state as in M3i plus banner (appended: jsonb_build_object takes at most 100 arguments)
create or replace function public.company_state(p_company uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  pc       public.player_companies;
  c        public.companies;
  v_team   jsonb;
  v_tier   jsonb;
  v_sb     jsonb;
  v_level  integer;
  v_cash   bigint;
  v_spread double precision;
  v_last   jsonb;
  v_hist   jsonb;
  v_cost   bigint;
begin
  select * into pc from public.player_companies where company_id = p_company;
  if pc.company_id is null then
    return null;
  end if;
  select * into c from public.companies where id = p_company;
  v_team := public.player_company_team(p_company);
  v_tier := public.company_tier_cfg(pc.tier);
  v_sb := public.company_tier_cfg('small_business');
  select p.level into v_level from public.profiles p where p.id = pc.founder_id;
  v_cash := coalesce((select a.balance_cents from public.ledger_accounts a where a.owner_company_id = p_company and a.kind = 'company_cash'), 0);
  v_spread := public.config_double('startups', '{estimate,initialSpread}', 2.3)
            * power(public.config_double('startups', '{estimate,decayPerQuarter}', 0.85), pc.quarters_active);
  select jsonb_build_object(
           'label', r.label, 'demand_cents', r.demand_cents, 'capacity_cents', r.capacity_cents,
           'revenue_cents', r.revenue_cents, 'cogs_cents', r.cogs_cents, 'fixed_cents', r.fixed_cents,
           'ai_worker_cents', r.ai_worker_cents, 'marketing_cents', r.marketing_cents, 'wages_cents', r.wages_cents,
           'operating_profit_cents', r.operating_profit_cents, 'utilization_bps', r.utilization_bps,
           'bonus_cents', r.bonus_cents)
    into v_last
    from public.player_company_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
   where r.company_id = p_company order by gq.ends_at desc limit 1;
  select coalesce(jsonb_agg(jsonb_build_object('label', h.label, 'revenue_cents', h.revenue_cents,
                                               'profit_cents', h.operating_profit_cents) order by h.ends_at), '[]'::jsonb)
    into v_hist
    from (select r.label, r.revenue_cents, r.operating_profit_cents, gq.ends_at
            from public.player_company_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
           where r.company_id = p_company order by gq.ends_at desc limit 12) h;
  v_cost := public.company_upgrade_cost(pc.tier);
  return jsonb_build_object(
    'id', c.id,
    'name', c.name,
    'idea', pc.idea,
    'sector', c.sector_key,
    'color', c.brand_color,
    'logo', public.company_logo(p_company),
    'logo_hidden', pc.logo_hidden,
    'founder_has_job', exists (select 1 from public.player_jobs x where x.player_id = pc.founder_id and x.status = 'active'),
    'full_time_from', public.config_double('startups', '{fullTimeFromEmployees}', 5)::integer,
    'training_from', public.config_double('startups', '{training,fromEmployees}', 5)::integer,
    'headcount', public.company_headcount(p_company),
    'tier', pc.tier,
    'founded_at', c.founded_at,
    'cash_cents', v_cash,
    'value_cents', public.company_value_cents(p_company),
    'unpaid_cents', pc.unpaid_cents,
    'distress', pc.distress,
    'distress_quarters', pc.distress_quarters,
    'grace_quarters', public.config_double('startups', '{insolvency,graceQuarters}', 4)::integer,
    'pay_factor_bps', pc.pay_factor_bps,
    'product_key', public.company_product(p_company) ->> 'key',
    'stage', (v_team ->> 'stage')::integer,
    'stages', public.company_stages_json(p_company),
    'awareness_bps', round(pc.awareness * 10000)::integer,
    'quality_bps', round(pc.quality * 10000)::integer,
    'quarters_active', pc.quarters_active,
    'estimate_low_cents', round(pc.potential_annual_cents
                                * exp(-v_spread * (0.3 + 0.7 * public.uniform_from_text(pc.company_id::text || ':' || pc.quarters_active || ':low'))))::bigint,
    'estimate_high_cents', round(pc.potential_annual_cents
                                 * exp(v_spread * (0.3 + 0.7 * public.uniform_from_text(pc.company_id::text || ':' || pc.quarters_active || ':high'))))::bigint,
    'marketing_cents_per_quarter', pc.marketing_cents_per_quarter,
    'ai_workers', pc.ai_workers,
    'ai_worker_cost_cents', public.config_bigint('startups', '{aiWorkerCostCentsPerQuarter}', 72000),
    'ai_wage_cents_per_hour', public.config_bigint('startups', '{aiWorkerWageCentsPerHour}', 12000),
    'ai_worker_skills', to_jsonb(pc.ai_worker_skills),
    'max_employees', (v_tier ->> 'maxEmployees')::integer,
    'employees', (v_team ->> 'employees')::integer,
    'open_postings', (select count(*) from public.job_postings jp where jp.company_id = p_company and jp.status = 'open')::integer,
    'pending_applications', (select count(*) from public.job_applications a join public.job_postings jp on jp.id = a.posting_id
                              where jp.company_id = p_company and a.status = 'pending')::integer,
    'founder_productivity_bps', (v_team ->> 'founder_productivity_bps')::integer,
    'team_productivity_bps', (v_team ->> 'team_productivity_bps')::integer,
    'capacity_cents', (v_team ->> 'capacity_cents')::bigint,
    'next_quarter_at', coalesce((public.current_game_quarter()).ends_at, public.game_now()),
    'can_upgrade', public.company_next_tier(pc.tier) is not null
                   and coalesce(v_level, 1) >= (public.company_tier_cfg(public.company_next_tier(pc.tier)) ->> 'minLevel')::integer,
    'listing', public.company_listing_json(p_company, pc.founder_id),
    'can_go_public', c.phase = 'private' and public.company_open_offer(p_company) is null
                     and coalesce(public.config_jsonb('startups', '{ipo,fromTiers}'), '["small_business", "gmbh"]'::jsonb) ? pc.tier
                     and coalesce(v_level, 1) >= public.config_double('startups', '{ipo,minLevel}', 12),
    'can_capital_increase', c.phase = 'listed' and public.company_open_offer(p_company) is null,
    'upgrade_cost_cents', v_cost,
    'last_quarter', v_last,
    'history', v_hist,
    'live', public.company_live_json(p_company),
    'hours', public.company_hours_json(p_company))
    || jsonb_build_object('banner', pc.banner);
end;
$$;

-- ---------------------------------------------------------------------------
-- E. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.logo_has_forbidden_symbol(jsonb)', 'public.banner_valid(jsonb)', 'public.company_state(uuid)',
    'public.set_company_banner(uuid, jsonb)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  execute 'grant execute on function public.set_company_banner(uuid, jsonb) to authenticated';
end;
$$;

-- ===== supabase/updates/20261122000100_m4a_artworks.sql =====
-- ===== idempotent copy of migrations/20261122000100_m4a_artworks.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · M4a · 0100 · Artworks: pixel art, gallery, auctions, collections (ADR-080)
-- =============================================================================
-- docs/ARTWORKS.md. Every artwork is unique (32 x 32 pixels, up to 16 colours).
-- The 36 artworks of the game (supabase/seeds/artworks.sql) belong to the NEXA
-- gallery (owner_id null), which auctions artworks.gallery.auctionsPerDay of them
-- per Berlin day. Players paint their own (the cost doubles with every artwork,
-- paid to the treasury), like, auction and bid. Bids are reserved in the system
-- account art_escrow; an outbid leader is refunded in the same posting. A sale pays
-- the seller the price minus artworks.auction.feeBps, the fee (gallery sales: all
-- of it) goes to the households. Value = last sale price; it counts towards the
-- net worth. Mirrors src/lib/sim/artworks.ts.
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. Ledger: transaction kinds and the escrow account
-- ---------------------------------------------------------------------------
-- (new enum values are only used inside PL/pgSQL bodies, so they may be added in
-- the same transaction that creates the functions)
alter type public.ledger_tx_kind add value if not exists 'artwork_creation';
alter type public.ledger_tx_kind add value if not exists 'artwork_bid';
alter type public.ledger_tx_kind add value if not exists 'artwork_refund';
alter type public.ledger_tx_kind add value if not exists 'artwork_sale';

insert into public.ledger_accounts (kind, system_key, label, allow_negative) values
  ('system', 'art_escrow', 'Artworks: reserved bids of running auctions (ADR-080)', false)
on conflict do nothing;

-- ---------------------------------------------------------------------------
-- B. Tables (internal: read through the RPCs, never written by clients)
-- ---------------------------------------------------------------------------
create table if not exists public.artworks (
  id          uuid primary key default gen_random_uuid(),
  serial      bigint not null unique check (serial > 0),
  gallery_key text unique,
  title       text not null check (char_length(title) between 1 and 80),
  origin      text not null check (origin in ('game', 'player')),
  rarity      text check (rarity in ('common', 'rare', 'legendary')),
  creator_id  uuid references public.profiles (id) on delete set null,
  owner_id    uuid references public.profiles (id) on delete set null,
  pixels      jsonb not null check (jsonb_typeof(pixels) = 'object' and pg_column_size(pixels) < 16384),
  value_cents bigint check (value_cents is null or value_cents > 0),
  created_at  timestamptz not null default now(),
  constraint artworks_origin_key check ((origin = 'game') = (gallery_key is not null))
);
alter table public.artworks enable row level security;
create index if not exists artworks_owner_idx on public.artworks (owner_id) where owner_id is not null;
create index if not exists artworks_creator_idx on public.artworks (creator_id) where creator_id is not null;
create index if not exists artworks_value_idx on public.artworks (value_cents desc) where value_cents is not null;
comment on table public.artworks is
  'Unique pixel artworks (ADR-080). serial = display code ART-0042; owner_id null = NEXA gallery; value_cents = last sale price (null = never sold). Internal (RPCs).';

create table if not exists public.artwork_auctions (
  id            uuid primary key default gen_random_uuid(),
  artwork_id    uuid not null references public.artworks (id) on delete cascade,
  seller_id     uuid references public.profiles (id) on delete set null,
  by_gallery    boolean not null default false,
  start_cents   bigint not null check (start_cents > 0),
  ends_at       timestamptz not null,
  status        text not null default 'open' check (status in ('open', 'sold', 'unsold', 'cancelled')),
  leader_id     uuid references public.profiles (id) on delete set null,
  current_cents bigint check (current_cents is null or current_cents > 0),
  bids          integer not null default 0 check (bids >= 0),
  created_at    timestamptz not null default now(),
  closed_at     timestamptz
);
alter table public.artwork_auctions enable row level security;
create index if not exists artwork_auctions_artwork_idx on public.artwork_auctions (artwork_id, created_at desc);
create unique index if not exists artwork_auctions_open_uq on public.artwork_auctions (artwork_id) where status = 'open';
create index if not exists artwork_auctions_due_idx on public.artwork_auctions (ends_at) where status = 'open';
create index if not exists artwork_auctions_seller_idx on public.artwork_auctions (seller_id) where seller_id is not null;
create index if not exists artwork_auctions_leader_idx on public.artwork_auctions (leader_id) where leader_id is not null;
create index if not exists artwork_auctions_gallery_idx on public.artwork_auctions (created_at) where by_gallery;
comment on table public.artwork_auctions is
  'Auctions of artworks; at most one open per artwork. by_gallery = started by the NEXA gallery (seller_id null). current_cents is held in art_escrow while open. Internal (RPCs).';

create table if not exists public.artwork_bids (
  id           bigint generated always as identity primary key,
  auction_id   uuid not null references public.artwork_auctions (id) on delete cascade,
  bidder_id    uuid not null references public.profiles (id) on delete cascade,
  amount_cents bigint not null check (amount_cents > 0),
  at           timestamptz not null default now()
);
alter table public.artwork_bids enable row level security;
create index if not exists artwork_bids_auction_idx on public.artwork_bids (auction_id, id desc);
create index if not exists artwork_bids_bidder_idx on public.artwork_bids (bidder_id);
comment on table public.artwork_bids is 'Every bid of an artwork auction (history). Internal (RPCs).';

create table if not exists public.artwork_likes (
  artwork_id uuid not null references public.artworks (id) on delete cascade,
  player_id  uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (artwork_id, player_id)
);
alter table public.artwork_likes enable row level security;
create index if not exists artwork_likes_player_idx on public.artwork_likes (player_id);
comment on table public.artwork_likes is 'One like per player and foreign artwork; can be taken back. Internal (RPCs).';

-- seller_id / buyer_id without foreign key: the sales history outlives a deleted player
create table if not exists public.artwork_sales (
  id          bigint generated always as identity primary key,
  artwork_id  uuid not null references public.artworks (id) on delete cascade,
  auction_id  uuid not null unique references public.artwork_auctions (id) on delete cascade,
  seller_id   uuid,
  buyer_id    uuid not null,
  price_cents bigint not null check (price_cents > 0),
  fee_cents   bigint not null default 0 check (fee_cents >= 0),
  at          timestamptz not null default now()
);
alter table public.artwork_sales enable row level security;
create index if not exists artwork_sales_artwork_idx on public.artwork_sales (artwork_id, at desc);
comment on table public.artwork_sales is
  'Completed artwork sales (seller_id null = gallery). fee_cents = what went to the households. Internal (RPCs).';

do $$
declare
  t text;
begin
  foreach t in array array['artworks', 'artwork_auctions', 'artwork_bids', 'artwork_likes', 'artwork_sales'] loop
    execute format('revoke all on public.%I from public, anon, authenticated', t);
    execute format('grant all on public.%I to service_role', t);
  end loop;
end;
$$;

-- ART-0001, ART-0002, ...: serials without gaps (the gallery seed runs with ON CONFLICT DO NOTHING
-- any number of times, so a sequence would lose numbers)
create or replace function public.artworks_assign_serial()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.serial is null then
    perform pg_advisory_xact_lock(7311080);
    select coalesce(max(a.serial), 0) + 1 into new.serial from public.artworks a;
  end if;
  return new;
end;
$$;
drop trigger if exists artworks_assign_serial on public.artworks;
create trigger artworks_assign_serial
  before insert on public.artworks
  for each row execute function public.artworks_assign_serial();

-- ---------------------------------------------------------------------------
-- C. Error keys (M4a: NX066..NX073)
-- ---------------------------------------------------------------------------
create or replace function public.api_error(p_key text)
returns void
language plpgsql
set search_path = ''
as $$
declare
  v_code text;
begin
  v_code := case p_key
    when 'insufficient_funds'          then 'NX001'
    when 'rate_limited'                then 'NX004'
    when 'forbidden'                   then 'NX006'
    when 'invalid_quantity'            then 'NX007'
    when 'invalid_price'               then 'NX007'
    when 'invalid_argument'            then 'NX007'
    when 'invalid_interval'            then 'NX007'
    when 'not_authenticated'           then 'NX010'
    when 'unknown_security'            then 'NX011'
    when 'not_tradable'                then 'NX012'
    when 'insufficient_position'       then 'NX013'
    when 'order_not_found'             then 'NX014'
    when 'order_not_open'              then 'NX015'
    when 'market_paused'               then 'NX016'
    when 'nothing_to_claim'            then 'NX017'
    when 'locked'                      then 'NX018'
    when 'name_too_short'              then 'NX019'
    when 'name_too_long'               then 'NX019'
    when 'name_invalid_chars'          then 'NX019'
    when 'name_profanity'              then 'NX019'
    when 'name_reserved'               then 'NX019'
    when 'name_taken'                  then 'NX019'
    when 'name_change_too_soon'        then 'NX020'
    when 'order_too_small'             then 'NX021'
    when 'market_illiquid'             then 'NX022'
    when 'mission_not_found'           then 'NX023'
    when 'mission_not_completed'       then 'NX024'
    when 'mission_already_claimed'     then 'NX025'
    when 'avatar_unknown'              then 'NX026'
    when 'avatar_locked'               then 'NX027'
    when 'daily_reward_claimed'        then 'NX028'
    when 'skill_unknown'               then 'NX029'
    when 'skill_learned'               then 'NX030'
    when 'skill_locked'                then 'NX031'
    when 'skill_points_insufficient'   then 'NX032'
    when 'job_not_found'               then 'NX033'
    when 'job_level_too_low'           then 'NX034'
    when 'job_skills_missing'          then 'NX035'
    when 'application_limit'           then 'NX036'
    when 'application_exists'          then 'NX037'
    when 'application_not_found'       then 'NX038'
    when 'application_not_offered'     then 'NX039'
    when 'offer_expired'               then 'NX040'
    when 'job_active_exists'           then 'NX041'
    when 'no_active_job'               then 'NX042'
    when 'raise_too_soon'              then 'NX043'
    when 'raise_too_high'              then 'NX044'
    when 'player_not_found'            then 'NX045'
    when 'employer_only'               then 'NX046'
    when 'company_exists'              then 'NX047'
    when 'company_not_found'           then 'NX048'
    when 'company_level_too_low'       then 'NX049'
    when 'owns_company'                then 'NX050'
    when 'employee_limit'              then 'NX051'
    when 'company_upgrade_unavailable' then 'NX052'
    when 'founding_locked'             then 'NX053'
    when 'not_in_company'              then 'NX054'
    when 'work_task_not_found'         then 'NX055'
    when 'work_task_expired'           then 'NX056'
    when 'work_task_done'              then 'NX057'
    when 'offer_closed'                then 'NX058'
    when 'offer_sold_out'              then 'NX059'
    when 'already_listed'              then 'NX060'
    when 'confirm_mismatch'            then 'NX061'
    when 'skill_already_covered'       then 'NX062'
    when 'training_locked'             then 'NX063'
    when 'logo_locked'                 then 'NX064'
    when 'logo_forbidden'              then 'NX065'
    when 'artworks_locked'             then 'NX066'
    when 'artwork_not_found'           then 'NX067'
    when 'auction_not_found'           then 'NX068'
    when 'auction_ended'               then 'NX069'
    when 'bid_too_low'                 then 'NX070'
    when 'own_artwork'                 then 'NX071'
    when 'already_on_auction'          then 'NX072'
    when 'auction_has_bids'            then 'NX073'
    else 'NX007'
  end;
  raise exception using errcode = v_code, message = p_key;
end;
$$;
comment on function public.api_error(text) is 'Raises the API error <key> with its NX SQLSTATE. The client shows a text per key (error.message).';

-- ---------------------------------------------------------------------------
-- D. Rules (port of src/lib/sim/artworks.ts)
-- ---------------------------------------------------------------------------
-- isValidArtwork: artworks.size rows of artworks.size chars from '.' and the palette
-- indices 0-9a-f below the palette length, 1..maxColors lowercase #rrggbb, >= 16 drawn pixels
create or replace function public.artwork_valid(p_art jsonb)
returns boolean
language plpgsql
stable
set search_path = ''
as $$
declare
  v_size integer := public.config_double('artworks', '{size}', 32)::integer;
  v_max  integer := public.config_double('artworks', '{maxColors}', 16)::integer;
  v_n    integer;
  v_re   text;
begin
  if p_art is null or jsonb_typeof(p_art) <> 'object'
     or jsonb_typeof(p_art -> 'palette') is distinct from 'array' or jsonb_typeof(p_art -> 'grid') is distinct from 'array' then
    return false;
  end if;
  v_n := jsonb_array_length(p_art -> 'palette');
  if v_n < 1 or v_n > least(v_max, 16)
     or exists (select 1 from jsonb_array_elements(p_art -> 'palette') c
                 where jsonb_typeof(c) <> 'string' or (c #>> '{}') !~ '^#[0-9a-f]{6}$') then
    return false;
  end if;
  if jsonb_array_length(p_art -> 'grid') <> v_size then
    return false;
  end if;
  v_re := '^[.' || substr('0123456789abcdef', 1, v_n) || ']{' || v_size || '}$';
  if exists (select 1 from jsonb_array_elements(p_art -> 'grid') r
              where jsonb_typeof(r) <> 'string' or (r #>> '{}') !~ v_re) then
    return false;
  end if;
  return (select sum(char_length(replace(r #>> '{}', '.', ''))) from jsonb_array_elements(p_art -> 'grid') r) >= 16;
end;
$$;
comment on function public.artwork_valid(jsonb) is 'Port of isValidArtwork (src/lib/sim/artworks.ts, ADR-080).';

-- artworkCreateCostCents: base x factor ^ artworks already painted (capped far below the bigint limit)
create or replace function public.artwork_create_cost_cents(p_painted integer)
returns bigint
language sql
stable
set search_path = ''
as $$
  select least(round(public.config_double('artworks', '{createBaseCostCents}', 1500000)::numeric
                     * power(public.config_double('artworks', '{createCostFactor}', 2)::numeric, greatest(0, coalesce(p_painted, 0)))),
               1000000000000000000)::bigint;
$$;

-- minNextBidCents: start price without a bid, else current + minIncrementBps, rounded up to whole euros
create or replace function public.artwork_min_bid_cents(p_start_cents bigint, p_current_cents bigint)
returns bigint
language sql
stable
set search_path = ''
as $$
  select case when p_current_cents is null then p_start_cents
              else (ceil(p_current_cents::numeric
                         * (10000 + public.config_double('artworks', '{auction,minIncrementBps}', 500)::integer)
                         / 1000000) * 100)::bigint end;
$$;

-- hotScore: (likes x likeWeight + bids x bidWeight + 1) / (age in hours + 2) ^ gravity
create or replace function public.artwork_hot(p_likes bigint, p_bids bigint, p_created timestamptz, p_now timestamptz)
returns double precision
language sql
stable
set search_path = ''
as $$
  select (coalesce(p_likes, 0) * public.config_double('artworks', '{hot,likeWeight}', 1)
          + coalesce(p_bids, 0) * public.config_double('artworks', '{hot,bidWeight}', 3) + 1)
         / power(greatest(0, extract(epoch from (p_now - p_created)) / 3600.0) + 2, public.config_double('artworks', '{hot,gravity}', 1.5));
$$;

create or replace function public.artwork_code(p_serial bigint)
returns text
language sql
immutable
set search_path = ''
as $$
  select 'ART-' || case when p_serial < 10000 then lpad(p_serial::text, 4, '0') else p_serial::text end;
$$;

-- Title: trimmed, single spaces, 3..artworks.titleMaxLength chars, letters (incl. umlauts), digits,
-- space and simple punctuation, at least one letter; words through the name filter (text_has_profanity).
-- Returns NULL or the reason (the name filter's keys).
create or replace function public.artwork_title_violation(p_title text)
returns text
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_max integer := public.config_double('artworks', '{titleMaxLength}', 40)::integer;
begin
  if p_title is null or char_length(p_title) < 3 then
    return 'name_too_short';
  end if;
  if char_length(p_title) > v_max then
    return 'name_too_long';
  end if;
  if p_title !~ '^[A-Za-zÄÖÜäöüßÀ-ÿ0-9 &.,:;!?''"()„“‚‘–-]+$' or public.name_letters(p_title) = '' then
    return 'name_invalid_chars';
  end if;
  if public.text_has_profanity(p_title) then
    return 'name_profanity';
  end if;
  return null;
end;
$$;
comment on function public.artwork_title_violation(text) is
  'Internal: NULL or name_too_short / name_too_long / name_invalid_chars / name_profanity for an artwork title (already trimmed).';

create or replace function public.artworks_require_unlock(p_player uuid)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if coalesce((select p.level from public.profiles p where p.id = p_player), 1) < public.unlock_level('artworks') then
    perform public.api_error('artworks_locked');
  end if;
end;
$$;

create or replace function public.player_art_value_cents(p_player uuid)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(sum(a.value_cents), 0)::bigint from public.artworks a where a.owner_id = p_player;
$$;
comment on function public.player_art_value_cents(uuid) is 'Value of the artworks a player owns (last sale prices; never sold = 0).';

create or replace function public.artwork_gallery_start_cents(p_rarity text)
returns bigint
language sql
stable
set search_path = ''
as $$
  select case p_rarity
           when 'legendary' then public.config_bigint('artworks', '{gallery,startPriceCents,legendary}', 15000000)
           when 'rare' then public.config_bigint('artworks', '{gallery,startPriceCents,rare}', 2500000)
           else public.config_bigint('artworks', '{gallery,startPriceCents,common}', 500000) end;
$$;

-- ---------------------------------------------------------------------------
-- E. ARTWORK (JSON of docs/ARTWORKS.md section 8)
-- ---------------------------------------------------------------------------
create or replace function public.artwork_json(p_artwork uuid, p_viewer uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  a       public.artworks;
  au      public.artwork_auctions;
  v_likes bigint;
  v_now   timestamptz := public.game_now();
begin
  select * into a from public.artworks where id = p_artwork;
  if a.id is null then
    return null;
  end if;
  select * into au from public.artwork_auctions x where x.artwork_id = a.id and x.status = 'open';
  select count(*) into v_likes from public.artwork_likes l where l.artwork_id = a.id;
  return jsonb_build_object(
    'id', a.id,
    'code', public.artwork_code(a.serial),
    'title', a.title,
    'origin', a.origin,
    'rarity', a.rarity,
    'creator', (select p.nickname from public.profiles p where p.id = a.creator_id),
    'owner', (select p.nickname from public.profiles p where p.id = a.owner_id),
    'pixels', jsonb_build_object('palette', a.pixels -> 'palette', 'grid', a.pixels -> 'grid'),
    'value_cents', a.value_cents,
    'likes', v_likes,
    'liked', exists (select 1 from public.artwork_likes l where l.artwork_id = a.id and l.player_id = p_viewer),
    'created_at', a.created_at,
    'hot', round(public.artwork_hot(v_likes, coalesce(au.bids, 0), a.created_at, v_now)::numeric, 6),
    'auction', case when au.id is null then null else jsonb_build_object(
      'id', au.id,
      'ends_at', au.ends_at,
      'start_cents', au.start_cents,
      'current_cents', au.current_cents,
      'min_bid_cents', public.artwork_min_bid_cents(au.start_cents, au.current_cents),
      'bids', au.bids,
      'leader', (select p.nickname from public.profiles p where p.id = au.leader_id),
      'seller', case when au.by_gallery then null
                     else coalesce((select p.nickname from public.profiles p where p.id = au.seller_id), 'Ehemaliger Spieler') end,
      'my_bid_cents', case when au.leader_id = p_viewer then au.current_cents end) end);
end;
$$;
comment on function public.artwork_json(uuid, uuid) is 'ARTWORK as seen by p_viewer (liked, my_bid_cents); docs/ARTWORKS.md section 8.';

-- ---------------------------------------------------------------------------
-- F. Settlement, gallery and the job
-- ---------------------------------------------------------------------------
-- Closes one auction if it is open and due: the leader gets the artwork, the seller the
-- price minus the fee, the households the fee (gallery: the whole price); without a bid
-- the artwork stays with its owner. Returns 'sold', 'unsold' or null (not due).
create or replace function public.artwork_settle_auction(p_auction uuid)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  au        public.artwork_auctions;
  v_now     timestamptz := public.game_now();
  v_fee     bigint;
  v_seller  uuid;
  v_escrow  uuid := public.ledger_system_account('art_escrow');
  v_house   uuid := public.ledger_system_account('households');
  v_entries jsonb;
  v_key     text;
begin
  select * into au from public.artwork_auctions where id = p_auction for update;
  if au.id is null or au.status <> 'open' or au.ends_at > v_now then
    return null;
  end if;
  if au.leader_id is null or au.current_cents is null then
    update public.artwork_auctions set status = 'unsold', closed_at = v_now where id = au.id;
    return 'unsold';
  end if;

  v_key := 'art:sale:' || au.id::text;
  -- seller: a player whose cash account can still receive money, else the households take it all
  if not au.by_gallery and au.seller_id is not null then
    select a.id into v_seller from public.ledger_accounts a
     where a.owner_player_id = au.seller_id and a.kind = 'player_cash' and not a.is_frozen;
  end if;
  if v_seller is null then
    v_fee := au.current_cents;
    v_entries := jsonb_build_array(jsonb_build_object('account_id', v_escrow, 'amount_cents', -au.current_cents),
                                   jsonb_build_object('account_id', v_house, 'amount_cents', au.current_cents));
  else
    v_fee := floor(au.current_cents * public.config_double('artworks', '{auction,feeBps}', 1000)::integer / 10000.0)::bigint;
    v_entries := jsonb_build_array(jsonb_build_object('account_id', v_escrow, 'amount_cents', -au.current_cents),
                                   jsonb_build_object('account_id', v_seller, 'amount_cents', au.current_cents - v_fee));
    if v_fee > 0 then
      v_entries := v_entries || jsonb_build_object('account_id', v_house, 'amount_cents', v_fee);
    end if;
  end if;
  perform public.ledger_post('artwork_sale', v_entries, 'Kunstwerk versteigert', 'artwork_auction', au.id, v_key, au.leader_id,
                             jsonb_build_object('price_cents', au.current_cents, 'fee_cents', v_fee, 'artwork_id', au.artwork_id));
  if v_seller is not null then
    perform public.loan_withhold(au.seller_id, au.current_cents - v_fee, v_key);
  end if;

  update public.artworks set owner_id = au.leader_id, value_cents = au.current_cents where id = au.artwork_id;
  insert into public.artwork_sales (artwork_id, auction_id, seller_id, buyer_id, price_cents, fee_cents, at)
  values (au.artwork_id, au.id, case when au.by_gallery then null else au.seller_id end, au.leader_id, au.current_cents, v_fee, v_now)
  on conflict (auction_id) do nothing;
  update public.artwork_auctions set status = 'sold', closed_at = v_now where id = au.id;

  perform public.mission_event(au.leader_id, 'art_won', 1, null);
  if not au.by_gallery then
    perform public.mission_event(au.seller_id, 'art_sold', 1, null);
  end if;
  return 'sold';
end;
$$;
comment on function public.artwork_settle_auction(uuid) is 'Internal: closes one due artwork auction (sale with fee, or unsold).';

-- The gallery auctions artworks.gallery.auctionsPerDay artworks per Berlin day, one per
-- slot of 24 h / auctionsPerDay (a job run that comes late starts the missed slots of the
-- day at once), each artworks.gallery.auctionHours long at its rarity's start price.
-- Candidates: artworks without owner and without an open auction, never auctioned by the
-- gallery today, unsold ones first, then the least often offered, then a daily shuffle.
create or replace function public.artworks_gallery_schedule(p_now timestamptz default null)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now     timestamptz := coalesce(p_now, public.game_now());
  v_day     date := (coalesce(p_now, public.game_now()) at time zone 'Europe/Berlin')::date;
  v_start   timestamptz;
  v_per     integer := greatest(0, public.config_double('artworks', '{gallery,auctionsPerDay}', 4)::integer);
  v_hours   double precision := greatest(0.1, public.config_double('artworks', '{gallery,auctionHours}', 6));
  v_due     integer;
  v_started integer;
  v_n       integer := 0;
  r         record;
begin
  if v_per = 0 then
    return 0;
  end if;
  v_start := v_day::timestamp at time zone 'Europe/Berlin';
  v_due := least(v_per, floor(extract(epoch from (v_now - v_start)) / (86400.0 / v_per))::integer + 1);
  select count(*) into v_started from public.artwork_auctions x
   where x.by_gallery and x.created_at >= v_start and x.created_at < v_start + interval '1 day';
  if v_started >= v_due then
    return 0;
  end if;
  for r in
    select a.id, a.rarity
      from public.artworks a
     where a.owner_id is null
       and not exists (select 1 from public.artwork_auctions x where x.artwork_id = a.id
                        and (x.status = 'open' or (x.by_gallery and x.created_at >= v_start)))
     order by (a.value_cents is null) desc,
              (select count(*) from public.artwork_auctions x where x.artwork_id = a.id and x.by_gallery),
              md5(a.id::text || v_day::text)
     limit v_due - v_started
  loop
    insert into public.artwork_auctions (artwork_id, seller_id, by_gallery, start_cents, ends_at, created_at)
    values (r.id, null, true, public.artwork_gallery_start_cents(r.rarity), v_now + make_interval(secs => v_hours * 3600), v_now)
    on conflict do nothing;
    if found then
      v_n := v_n + 1;
    end if;
  end loop;
  return v_n;
end;
$$;
comment on function public.artworks_gallery_schedule(timestamptz) is
  'Internal: starts the gallery auctions due today (artworks.gallery, ADR-080). Idempotent.';

create or replace function public.artworks_run_due()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_sold   integer := 0;
  v_unsold integer := 0;
  v_res    text;
  r        record;
begin
  for r in select x.id from public.artwork_auctions x
            where x.status = 'open' and x.ends_at <= public.game_now()
            order by x.ends_at, x.id limit 200 loop
    v_res := public.artwork_settle_auction(r.id);
    if v_res = 'sold' then
      v_sold := v_sold + 1;
    elsif v_res = 'unsold' then
      v_unsold := v_unsold + 1;
    end if;
  end loop;
  return jsonb_build_object('sold', v_sold, 'unsold', v_unsold, 'gallery_started', public.artworks_gallery_schedule(null));
end;
$$;
comment on function public.artworks_run_due() is 'Internal (run_due_jobs): closes due artwork auctions, then schedules the gallery.';

-- Account reset/delete: the player's artworks go back to the gallery, auctions they sell are
-- cancelled (the leader is refunded), auctions they lead lose them as leader (their money
-- comes back to their cash before account_wipe returns it to the state), likes disappear.
create or replace function public.artworks_wipe_player(p_player uuid, p_key text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_escrow uuid := public.ledger_system_account('art_escrow');
  r        record;
begin
  for r in select x.* from public.artwork_auctions x where x.status = 'open' and (x.seller_id = p_player or x.leader_id = p_player)
            order by x.id for update loop
    if r.leader_id is not null and r.current_cents is not null then
      perform public.ledger_transfer(v_escrow, public.ledger_player_account(r.leader_id, 'player_cash'), r.current_cents,
                                     'artwork_refund', 'Gebot zurück (Auktion beendet)', 'artwork_auction', r.id,
                                     p_key || ':art:' || r.id::text, r.leader_id);
    end if;
    if r.seller_id = p_player then
      update public.artwork_auctions set status = 'cancelled', closed_at = public.game_now() where id = r.id;
    else
      delete from public.artwork_bids b where b.auction_id = r.id and b.bidder_id = p_player;
      update public.artwork_auctions
         set leader_id = null, current_cents = null,
             bids = (select count(*) from public.artwork_bids b where b.auction_id = r.id)
       where id = r.id;
    end if;
  end loop;
  update public.artworks set owner_id = null where owner_id = p_player;
  delete from public.artwork_likes where player_id = p_player;
end;
$$;
comment on function public.artworks_wipe_player(uuid, text) is 'Internal (account_wipe): releases the artworks, auctions and bids of a player.';

-- ---------------------------------------------------------------------------
-- G. Read RPCs
-- ---------------------------------------------------------------------------
create or replace function public.get_artworks(p_sort text default 'hot', p_origin text default 'all',
                                               p_on_auction boolean default false, p_limit integer default 24,
                                               p_offset integer default 0)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player  uuid;
  v_sort    text := coalesce(p_sort, 'hot');
  v_origin  text := coalesce(p_origin, 'all');
  v_auction boolean := coalesce(p_on_auction, false);
  v_limit   integer := least(greatest(coalesce(p_limit, 24), 1), 100);
  v_offset  integer := greatest(coalesce(p_offset, 0), 0);
  v_now     timestamptz := public.game_now();
  v_total   bigint;
  v_entries jsonb;
begin
  v_player := public.require_player();
  if v_sort not in ('hot', 'price', 'new', 'ending') or v_origin not in ('all', 'game', 'player') then
    perform public.api_error('invalid_argument');
  end if;
  with base as (
    select a.id, a.serial, a.created_at,
           coalesce(au.current_cents, a.value_cents, au.start_cents) as price,
           au.ends_at,
           public.artwork_hot((select count(*) from public.artwork_likes l where l.artwork_id = a.id),
                              coalesce(au.bids, 0), a.created_at, v_now) as hot
      from public.artworks a
      left join public.artwork_auctions au on au.artwork_id = a.id and au.status = 'open'
     where (v_origin = 'all' or a.origin = v_origin)
       and (not v_auction or au.id is not null)
  ), ordered as (
    select b.id,
           row_number() over (order by
             case when v_sort = 'hot' then b.hot end desc nulls last,
             case when v_sort = 'price' then b.price end desc nulls last,
             case when v_sort = 'new' then b.created_at end desc nulls last,
             case when v_sort = 'ending' then b.ends_at end asc nulls last,
             b.hot desc, b.serial desc) as ord,
           count(*) over () as total
      from base b
  )
  select coalesce(max(o.total), 0),
         coalesce(jsonb_agg(public.artwork_json(o.id, v_player) order by o.ord)
                    filter (where o.ord > v_offset and o.ord <= v_offset + v_limit), '[]'::jsonb)
    into v_total, v_entries
    from ordered o;
  return jsonb_build_object('server_time', v_now, 'total', v_total, 'entries', v_entries);
end;
$$;
comment on function public.get_artworks(text, text, boolean, integer, integer) is
  'RPC: marketplace page {server_time, total, entries: [ARTWORK]}; sort hot|price|new|ending, origin all|game|player (ADR-080).';

create or replace function public.get_artwork(p_artwork_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player  uuid;
  v_auction uuid;
begin
  v_player := public.require_player();
  if p_artwork_id is null or not exists (select 1 from public.artworks a where a.id = p_artwork_id) then
    perform public.api_error('artwork_not_found');
  end if;
  -- bids of the running auction, else of the latest one
  select x.id into v_auction from public.artwork_auctions x where x.artwork_id = p_artwork_id
   order by (x.status = 'open') desc, x.created_at desc, x.id limit 1;
  return jsonb_build_object(
    'artwork', public.artwork_json(p_artwork_id, v_player),
    'sales', coalesce((select jsonb_agg(jsonb_build_object(
                         'at', s.at, 'price_cents', s.price_cents,
                         'seller', case when s.seller_id is null then null
                                        else coalesce(ps.nickname, 'Ehemaliger Spieler') end,
                         'buyer', coalesce(pb.nickname, 'Ehemaliger Spieler')) order by s.at desc, s.id desc)
                         from public.artwork_sales s
                         left join public.profiles ps on ps.id = s.seller_id
                         left join public.profiles pb on pb.id = s.buyer_id
                        where s.artwork_id = p_artwork_id), '[]'::jsonb),
    'bids', coalesce((select jsonb_agg(jsonb_build_object('nickname', coalesce(p.nickname, 'Ehemaliger Spieler'),
                                                          'amount_cents', b.amount_cents, 'at', b.at) order by b.id desc)
                        from (select * from public.artwork_bids b0 where b0.auction_id = v_auction order by b0.id desc limit 50) b
                        left join public.profiles p on p.id = b.bidder_id), '[]'::jsonb));
end;
$$;
comment on function public.get_artwork(uuid) is
  'RPC: {artwork: ARTWORK, sales: [{at, price_cents, seller, buyer}], bids: [{nickname, amount_cents, at}]} (ADR-080).';

create or replace function public.get_art_studio()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player  uuid;
  v_painted integer;
begin
  v_player := public.require_player();
  select count(*) into v_painted from public.artworks a where a.creator_id = v_player;
  return jsonb_build_object(
    'painted', v_painted,
    'next_cost_cents', public.artwork_create_cost_cents(v_painted),
    'unlocked', coalesce((select p.level from public.profiles p where p.id = v_player), 1) >= public.unlock_level('artworks'));
end;
$$;
comment on function public.get_art_studio() is 'RPC: {painted, next_cost_cents, unlocked} for the art editor (ADR-080).';

create or replace function public.get_art_rankings(p_limit integer default 10)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_limit  integer := least(greatest(coalesce(p_limit, 10), 1), 100);
begin
  v_player := public.require_player();
  return jsonb_build_object(
    'collections', coalesce((
      select jsonb_agg(jsonb_build_object('rank', c.rnk, 'nickname', c.nickname, 'avatar_key', c.avatar_key,
                                          'count', c.n, 'value_cents', c.val, 'is_me', c.owner_id = v_player) order by c.rnk)
        from (select x.*, row_number() over (order by x.val desc, x.n desc, lower(x.nickname)) as rnk
                from (select a.owner_id, p.nickname, p.avatar_key, count(*) as n, coalesce(sum(a.value_cents), 0)::bigint as val
                        from public.artworks a join public.profiles p on p.id = a.owner_id
                       where not p.is_deactivated
                       group by a.owner_id, p.nickname, p.avatar_key) x) c
       where c.rnk <= v_limit), '[]'::jsonb),
    'artworks', coalesce((
      select jsonb_agg(jsonb_build_object('rank', t.rnk, 'artwork', public.artwork_json(t.id, v_player)) order by t.rnk)
        from (select a.id, row_number() over (order by a.value_cents desc, a.serial) as rnk
                from public.artworks a where a.value_cents is not null
               order by a.value_cents desc, a.serial limit v_limit) t), '[]'::jsonb));
end;
$$;
comment on function public.get_art_rankings(integer) is
  'RPC: largest collections (sum of values) and most valuable artworks (ADR-080).';

-- p_nickname null = the caller
create or replace function public.get_collection(p_nickname text default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_target uuid;
  v_nick   text;
begin
  v_player := public.require_player();
  if p_nickname is null then
    v_target := v_player;
  else
    select p.id into v_target from public.profiles p where lower(p.nickname) = lower(btrim(p_nickname));
  end if;
  select p.nickname into v_nick from public.profiles p where p.id = v_target;
  if v_nick is null then
    perform public.api_error('player_not_found');
  end if;
  return jsonb_build_object(
    'nickname', v_nick,
    'count', (select count(*) from public.artworks a where a.owner_id = v_target),
    'value_cents', public.player_art_value_cents(v_target),
    'artworks', coalesce((select jsonb_agg(public.artwork_json(a.id, v_player)
                                           order by a.value_cents desc nulls last, a.created_at desc, a.serial desc)
                            from public.artworks a where a.owner_id = v_target), '[]'::jsonb));
end;
$$;
comment on function public.get_collection(text) is 'RPC: {nickname, count, value_cents, artworks: [ARTWORK]} of a player (ADR-080).';

-- ---------------------------------------------------------------------------
-- H. Write RPCs (unlock level artworks, idempotent per request_id)
-- ---------------------------------------------------------------------------
create or replace function public.create_artwork(p_request_id uuid, p_title text, p_pixels jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player  uuid;
  v_replay  jsonb;
  v_title   text := btrim(regexp_replace(coalesce(p_title, ''), '\s+', ' ', 'g'));
  v_reason  text;
  v_painted integer;
  v_cost    bigint;
  v_cash    bigint;
  v_id      uuid := gen_random_uuid();
begin
  v_player := public.require_player();
  perform public.artworks_require_unlock(v_player);
  if p_request_id is null or not public.artwork_valid(p_pixels) then
    perform public.api_error('invalid_argument');
  end if;
  v_reason := public.artwork_title_violation(v_title);
  if v_reason is not null then
    perform public.api_error(v_reason);
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'create_artwork');
  if v_replay is not null then
    return v_replay;
  end if;
  if public.logo_has_forbidden_symbol(p_pixels -> 'grid') then
    perform public.api_error('logo_forbidden');
  end if;
  -- one painting at a time per player (the count decides the price)
  perform 1 from public.profiles p where p.id = v_player for update;
  select count(*) into v_painted from public.artworks a where a.creator_id = v_player;
  v_cost := public.artwork_create_cost_cents(v_painted);
  v_cash := public.lock_player_accounts(v_player);
  if v_cash < v_cost then
    perform public.api_error('insufficient_funds');
  end if;
  perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), public.ledger_system_account('treasury'),
                                 v_cost, 'artwork_creation', 'Kunstwerk gemalt', 'artwork', v_id,
                                 'art:create:' || v_id::text, v_player, jsonb_build_object('painted_before', v_painted));
  insert into public.artworks (id, title, origin, rarity, creator_id, owner_id, pixels)
  values (v_id, v_title, 'player', null, v_player, v_player,
          jsonb_build_object('palette', p_pixels -> 'palette', 'grid', p_pixels -> 'grid'));
  perform public.mission_event(v_player, 'art_painted', 1, null);
  return public.request_complete(v_player, p_request_id, jsonb_build_object(
    'artwork', public.artwork_json(v_id, v_player),
    'cost_cents', v_cost,
    'next_cost_cents', public.artwork_create_cost_cents(v_painted + 1)));
end;
$$;
comment on function public.create_artwork(uuid, text, jsonb) is
  'RPC: paints a new artwork (cost doubles per artwork, paid to the treasury); errors artworks_locked, invalid_argument, name_*, logo_forbidden, insufficient_funds.';

create or replace function public.like_artwork(p_request_id uuid, p_artwork_id uuid, p_like boolean)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  a        public.artworks;
begin
  v_player := public.require_player();
  perform public.artworks_require_unlock(v_player);
  if p_request_id is null or p_artwork_id is null or p_like is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'like_artwork');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into a from public.artworks where id = p_artwork_id;
  if a.id is null then
    perform public.api_error('artwork_not_found');
  end if;
  if a.owner_id = v_player or a.creator_id = v_player then
    perform public.api_error('own_artwork');
  end if;
  if p_like then
    insert into public.artwork_likes (artwork_id, player_id) values (a.id, v_player) on conflict do nothing;
    if found then
      perform public.mission_event(v_player, 'art_like', 1, a.id::text);
    end if;
  else
    delete from public.artwork_likes where artwork_id = a.id and player_id = v_player;
  end if;
  return public.request_complete(v_player, p_request_id, jsonb_build_object(
    'likes', (select count(*) from public.artwork_likes l where l.artwork_id = a.id),
    'liked', p_like));
end;
$$;
comment on function public.like_artwork(uuid, uuid, boolean) is
  'RPC: likes (p_like true) or unlikes a foreign artwork; errors artworks_locked, artwork_not_found, own_artwork.';

create or replace function public.start_auction(p_request_id uuid, p_artwork_id uuid, p_start_cents bigint, p_hours integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  a        public.artworks;
  v_now    timestamptz := public.game_now();
begin
  v_player := public.require_player();
  perform public.artworks_require_unlock(v_player);
  if p_request_id is null or p_artwork_id is null or p_hours is null or p_start_cents is null
     or p_start_cents < public.config_bigint('artworks', '{auction,minStartCents}', 10000)
     or not (coalesce(public.config_jsonb('artworks', '{auction,durationsHours}'), '[1, 6, 24]'::jsonb) @> to_jsonb(p_hours)) then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'start_auction');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into a from public.artworks where id = p_artwork_id for update;
  if a.id is null then
    perform public.api_error('artwork_not_found');
  end if;
  if a.owner_id is distinct from v_player then
    perform public.api_error('forbidden');
  end if;
  if exists (select 1 from public.artwork_auctions x where x.artwork_id = a.id and x.status = 'open') then
    perform public.api_error('already_on_auction');
  end if;
  insert into public.artwork_auctions (artwork_id, seller_id, by_gallery, start_cents, ends_at, created_at)
  values (a.id, v_player, false, p_start_cents, v_now + make_interval(hours => p_hours), v_now);
  perform public.mission_event(v_player, 'art_auction_started', 1, null);
  return public.request_complete(v_player, p_request_id, jsonb_build_object('artwork', public.artwork_json(a.id, v_player)));
end;
$$;
comment on function public.start_auction(uuid, uuid, bigint, integer) is
  'RPC: the owner offers an artwork (start >= artworks.auction.minStartCents, hours in durationsHours); errors forbidden, already_on_auction.';

create or replace function public.cancel_auction(p_request_id uuid, p_auction_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  au       public.artwork_auctions;
begin
  v_player := public.require_player();
  perform public.artworks_require_unlock(v_player);
  if p_request_id is null or p_auction_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'cancel_auction');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into au from public.artwork_auctions where id = p_auction_id for update;
  if au.id is null then
    perform public.api_error('auction_not_found');
  end if;
  if au.by_gallery or au.seller_id is distinct from v_player then
    perform public.api_error('forbidden');
  end if;
  if au.status <> 'open' then
    perform public.api_error('auction_ended');
  end if;
  if au.leader_id is not null then
    perform public.api_error('auction_has_bids');
  end if;
  update public.artwork_auctions set status = 'cancelled', closed_at = public.game_now() where id = au.id;
  return public.request_complete(v_player, p_request_id, jsonb_build_object('artwork', public.artwork_json(au.artwork_id, v_player)));
end;
$$;
comment on function public.cancel_auction(uuid, uuid) is
  'RPC: the seller cancels an auction without a bid; errors auction_not_found, forbidden, auction_ended, auction_has_bids.';

-- One posting per bid: the previous leader's reservation goes back to them and the new bid
-- moves from the bidder's cash into art_escrow (accounts locked together, in id order).
create or replace function public.bid_artwork(p_request_id uuid, p_auction_id uuid, p_amount_cents bigint)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player  uuid;
  v_replay  jsonb;
  au        public.artwork_auctions;
  v_owner   uuid;
  v_now     timestamptz := public.game_now();
  v_min     bigint;
  v_cash    bigint;
  v_escrow  uuid := public.ledger_system_account('art_escrow');
  v_entries jsonb := '[]'::jsonb;
  v_window  double precision := public.config_double('artworks', '{auction,antiSnipeMinutes}', 2) * 60;
  v_bid     bigint;
begin
  v_player := public.require_player();
  perform public.artworks_require_unlock(v_player);
  if p_request_id is null or p_auction_id is null or p_amount_cents is null or p_amount_cents < 1 then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'bid_artwork');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into au from public.artwork_auctions where id = p_auction_id for update;
  if au.id is null then
    perform public.api_error('auction_not_found');
  end if;
  if au.status <> 'open' or au.ends_at <= v_now then
    perform public.api_error('auction_ended');
  end if;
  select a.owner_id into v_owner from public.artworks a where a.id = au.artwork_id;
  if au.seller_id = v_player or v_owner = v_player then
    perform public.api_error('own_artwork');
  end if;
  v_min := public.artwork_min_bid_cents(au.start_cents, au.current_cents);
  if p_amount_cents < v_min then
    perform public.api_error('bid_too_low');
  end if;
  select a.balance_cents into v_cash from public.ledger_accounts a where a.owner_player_id = v_player and a.kind = 'player_cash';
  if coalesce(v_cash, 0) + (case when au.leader_id = v_player then au.current_cents else 0 end) < p_amount_cents then
    perform public.api_error('insufficient_funds');
  end if;

  if au.leader_id is not null and au.current_cents is not null then
    v_entries := jsonb_build_array(
      jsonb_build_object('account_id', v_escrow, 'amount_cents', -au.current_cents),
      jsonb_build_object('account_id', public.ledger_player_account(au.leader_id, 'player_cash'), 'amount_cents', au.current_cents));
  end if;
  v_entries := v_entries
    || jsonb_build_object('account_id', public.ledger_player_account(v_player, 'player_cash'), 'amount_cents', -p_amount_cents)
    || jsonb_build_object('account_id', v_escrow, 'amount_cents', p_amount_cents);
  insert into public.artwork_bids (auction_id, bidder_id, amount_cents, at) values (au.id, v_player, p_amount_cents, v_now)
  returning id into v_bid;
  begin
    perform public.ledger_post('artwork_bid', v_entries, 'Gebot auf ein Kunstwerk', 'artwork_auction', au.id,
                               'art:bid:' || v_bid::text, v_player,
                               jsonb_build_object('amount_cents', p_amount_cents, 'refunded_player', au.leader_id,
                                                  'refunded_cents', au.current_cents));
  exception when sqlstate 'NX001' then
    perform public.api_error('insufficient_funds');
  end;
  update public.artwork_auctions
     set leader_id = v_player, current_cents = p_amount_cents, bids = bids + 1,
         ends_at = case when extract(epoch from (au.ends_at - v_now)) < v_window
                        then v_now + make_interval(secs => v_window) else au.ends_at end
   where id = au.id;
  perform public.mission_event(v_player, 'art_bid', 1, null);
  return public.request_complete(v_player, p_request_id, jsonb_build_object('artwork', public.artwork_json(au.artwork_id, v_player)));
end;
$$;
comment on function public.bid_artwork(uuid, uuid, bigint) is
  'RPC: bids on an artwork auction (reserved in art_escrow, previous leader refunded, anti-snipe); errors auction_not_found, auction_ended, own_artwork, bid_too_low, insufficient_funds.';

-- ---------------------------------------------------------------------------
-- I. Net worth with art (rich list, player card, state missions)
-- ---------------------------------------------------------------------------
create or replace function public.player_net_worth_cents(p_player uuid)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select sum(a.balance_cents) from public.ledger_accounts a where a.owner_player_id = p_player), 0)::bigint
       + coalesce((select sum(public.value_cents(p.quantity_e6, coalesce(q.bid_e4, q.last_price_e4)))
                     from public.positions p join public.security_quotes q on q.security_id = p.security_id
                    where p.player_id = p_player and p.status = 'open' and p.quantity_e6 > 0), 0)::bigint
       -- founder's player company (ADR-057): cash - unpaid + earnings value
       + public.player_company_value_cents(p_player)
       -- artworks at their last sale price (ADR-080)
       + public.player_art_value_cents(p_player)
       - public.player_debt_cents(p_player);
$$;

-- rich_list_entries as in M3d plus the value of the artworks
create or replace function public.rich_list_entries()
returns table (entity_kind text, entity_id uuid, name text, description text, net_worth_cents bigint, rank_all integer, rank_players integer)
language sql
stable
security definer
set search_path = ''
as $$
  with players as (
    select p.id,
           coalesce(a.cash, 0) + coalesce(v.val, 0) + coalesce(public.company_value_cents(pc.company_id), 0)
             + coalesce(art.val, 0) - coalesce(d.debt, 0) as nw,
           p.nickname
      from public.profiles p
      left join (select owner_player_id, sum(balance_cents)::bigint as cash from public.ledger_accounts
                  where owner_player_id is not null group by owner_player_id) a on a.owner_player_id = p.id
      left join (select pos.player_id, sum(public.value_cents(pos.quantity_e6, coalesce(q.bid_e4, q.last_price_e4)))::bigint as val
                   from public.positions pos join public.security_quotes q on q.security_id = pos.security_id
                  where pos.status = 'open' and pos.quantity_e6 > 0 group by pos.player_id) v on v.player_id = p.id
      left join public.player_companies pc on pc.founder_id = p.id and pc.status = 'active'
      left join (select l.player_id, sum(l.outstanding_cents)::bigint as debt from public.player_loans l
                  where l.status = 'open' group by l.player_id) d on d.player_id = p.id
      left join (select aw.owner_id, sum(aw.value_cents)::bigint as val from public.artworks aw
                  where aw.owner_id is not null and aw.value_cents is not null group by aw.owner_id) art on art.owner_id = p.id
     where not p.is_deactivated
  ), tycoons as (
    select t.id, t.name, t.description,
           t.cash_cents + coalesce(sum(public.value_cents(h.quantity_e6, coalesce(q.bid_e4, q.last_price_e4))), 0)::bigint as nw
      from public.rich_tycoons t
      left join public.rich_tycoon_holdings h on h.tycoon_id = t.id
      left join public.security_quotes q on q.security_id = h.security_id
     group by t.id
  ), allx as (
    select 'player'::text as entity_kind, id as entity_id, nickname as name, null::text as description, nw from players
    union all
    select 'tycoon', id, name, description, nw from tycoons
  )
  select x.entity_kind, x.entity_id, x.name, x.description, x.nw,
         (row_number() over (order by x.nw desc, x.entity_kind, x.entity_id))::integer,
         case when x.entity_kind = 'player'
              then (row_number() over (partition by x.entity_kind order by x.nw desc, x.entity_id))::integer end
    from allx x;
$$;

-- ---------------------------------------------------------------------------
-- J. Account reset/delete releases artworks (account_wipe as in M3g plus artworks)
-- ---------------------------------------------------------------------------
create or replace function public.account_wipe(p_player uuid, p_key text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_nick    text;
  v_company uuid;
  v_state   uuid := public.ledger_system_account(case when public.money_genesis_done() then 'treasury' else 'mint' end);
  v_bal     bigint;
  r         record;
begin
  perform public.lock_player_accounts(p_player);
  select p.nickname into v_nick from public.profiles p where p.id = p_player for update;

  -- artworks (ADR-080): back to the gallery, auctions cancelled, reserved bids back to the cash
  perform public.artworks_wipe_player(p_player, p_key);

  -- own company: open share offers are settled first, then it is dissolved like close_company
  select pc.company_id into v_company from public.player_companies pc where pc.founder_id = p_player and pc.status = 'active';
  if v_company is not null then
    for r in select o.id from public.company_share_offers o where o.company_id = v_company and o.status = 'open' order by o.id loop
      perform public.close_share_offer(r.id);
    end loop;
    perform public.company_dissolve(v_company, 'closed');
  end if;

  -- subscriptions to other companies' open offers lapse (the money stays with the company)
  for r in select s.offer_id, sum(s.shares_e6)::bigint as q from public.offer_subscriptions s
            join public.company_share_offers o on o.id = s.offer_id and o.status = 'open'
           where s.player_id = p_player group by s.offer_id order by s.offer_id loop
    update public.company_share_offers set shares_subscribed_e6 = greatest(0, shares_subscribed_e6 - r.q) where id = r.offer_id;
  end loop;

  -- job: wages up to now, then ended without notice or fee
  for r in select pj.id, pj.company_id from public.player_jobs pj where pj.player_id = p_player and pj.status = 'active' order by pj.id loop
    perform public.accrue_job_salary(r.id);
    update public.player_jobs set status = 'ended', ended_at = now(), end_reason = 'quit', notice_ends_at = null where id = r.id;
    perform public.company_system_message(r.company_id, v_nick || ' hat das Unternehmen verlassen.');
  end loop;

  -- open orders release their reservations; holdings are given up
  for r in select o.id from public.orders o
            where o.player_id = p_player and o.status in ('pending', 'open', 'partially_filled') order by o.id loop
    perform public.cancel_order_internal(r.id);
  end loop;
  update public.positions
     set status = 'closed', closed_at = now(), quantity_e6 = 0, reserved_quantity_e6 = 0, cost_basis_cents = 0,
         margin_cents = 0, borrowed_cents = 0, liquidation_price_e4 = null
   where player_id = p_player and status = 'open';

  -- game state of the player
  for r in select * from (values
             ('position_lots', 'player_id'), ('xp_events', 'player_id'), ('xp_daily_counters', 'player_id'),
             ('vault_claims', 'player_id'), ('daily_logins', 'player_id'), ('player_missions', 'player_id'),
             ('player_achievements', 'player_id'), ('player_cosmetics', 'player_id'), ('player_lifestyle_items', 'player_id'),
             ('player_random_events', 'player_id'), ('player_bankruptcies', 'player_id'), ('margin_events', 'player_id'),
             ('financing_charges', 'player_id'), ('player_tax_years', 'player_id'), ('distribution_payouts', 'player_id'),
             ('watchlist_items', 'player_id'), ('portfolio_snapshots', 'player_id'), ('stock_option_grants', 'player_id'),
             ('loans', 'player_id'), ('cap_table_entries', 'player_id'), ('share_lockups', 'player_id'),
             ('capital_injections', 'player_id'), ('takeover_offers', 'bidder_player_id'), ('angel_offers', 'investor_player_id'),
             ('ipo_subscriptions', 'player_id'), ('shareholder_vote_ballots', 'player_id'), ('reputation_events', 'player_id'),
             ('insider_violations', 'player_id'), ('salary_payouts', 'player_id'), ('work_tasks', 'player_id'),
             ('salary_negotiations', 'player_id'), ('player_work_tasks', 'player_id'), ('player_jobs', 'player_id'),
             ('job_offers', 'to_player_id'), ('job_applications', 'player_id'), ('player_skills', 'player_id'),
             ('player_skill_points', 'player_id'), ('daily_reward_claims', 'player_id'), ('player_loans', 'player_id'),
             ('offer_subscriptions', 'player_id'), ('notifications', 'player_id'), ('feed_items', 'actor_id'),
             ('league_entries', 'player_id'), ('league_entry_baselines', 'player_id'), ('company_logo_reports', 'reporter_id'),
             ('player_unlocks', 'player_id')
           ) as t(tbl, col) loop
    execute format('delete from public.%I where %I = $1', r.tbl, r.col) using p_player;
  end loop;
  delete from public.rich_list_snapshots where entity_kind = 'player' and entity_id = p_player;

  -- money back to the state: one balanced posting per account
  for r in select a.id from public.ledger_accounts a where a.owner_player_id = p_player and a.balance_cents > 0 order by a.id loop
    select a.balance_cents into v_bal from public.ledger_accounts a where a.id = r.id;
    perform public.ledger_transfer(r.id, v_state, v_bal, 'transfer', 'Konto zurückgesetzt', 'profile', p_player,
                                   p_key || ':' || r.id::text, p_player);
  end loop;

  update public.profiles
     set level = 1, xp_total = 0, reputation = 50, title_key = null, frame_key = null,
         bankrupt_until = null, founding_locked_until = null
   where id = p_player;
  update public.player_private
     set founding_ban_until = null, bankruptcy_count = 0, career_experience_minutes = 0, ipo_investment_limit_cents = null,
         tutorial_completed_at = null, tax_loss_pot_cents = 0
   where player_id = p_player;
end;
$$;
comment on function public.account_wipe(uuid, text) is 'Internal: cleanup shared by reset_account() and delete_account().';

-- ---------------------------------------------------------------------------
-- K. run_due_jobs as in M3i plus artworks (auctions, gallery)
-- ---------------------------------------------------------------------------
create or replace function public.run_due_jobs()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now      timestamptz;
  v_result   jsonb := '{}'::jsonb;
  v_closed   jsonb := '[]'::jsonb;
  v_latest   bigint;
  q          record;
  v_run      bigint;
begin
  -- waits for a running tick (ticks only try the lock and skip)
  perform pg_advisory_xact_lock(7311001);
  v_now := public.game_now();
  perform public.ensure_game_quarters(3);

  if not exists (select 1 from public.candles limit 1) or not public.money_genesis_done()
     or not exists (select 1 from public.rich_tycoons) then
    v_result := v_result || jsonb_build_object('bootstrap', public.market_bootstrap());
  end if;

  -- first run on a database: older quarters are skipped, only the latest ended one is closed
  if not exists (select 1 from public.job_runs j where j.job_name = 'quarter_close') then
    select gq.id into v_latest from public.game_quarters gq
     where gq.ends_at <= v_now and gq.status <> 'closed' order by gq.ends_at desc limit 1;
    for q in select gq.id from public.game_quarters gq
              where gq.ends_at <= v_now and gq.status <> 'closed' and gq.id <> coalesce(v_latest, -1)
    loop
      update public.game_quarters set status = 'closed', closed_at = now() where id = q.id;
      insert into public.job_runs (job_name, run_key, status, finished_at, details)
      values ('quarter_close', q.id::text, 'succeeded', now(), '{"skipped": "before_first_run"}'::jsonb)
      on conflict do nothing;
    end loop;
  end if;

  for q in select gq.id from public.game_quarters gq
            where gq.ends_at <= v_now and gq.status <> 'closed'
            order by gq.ends_at limit 8
  loop
    v_closed := v_closed || public.close_game_quarter(q.id);
  end loop;
  v_result := v_result || jsonb_build_object('quarters', v_closed);
  -- player companies: operating hours (ADR-072), then every closed quarter since their founding (ADR-057)
  v_result := v_result || jsonb_build_object('player_companies', public.player_companies_run_due());

  -- bonds that matured between quarter closes (or after a downtime)
  if exists (select 1 from public.bonds bd join public.securities s on s.id = bd.security_id
              where s.status = 'listed' and bd.matures_at <= v_now) then
    v_result := v_result || jsonb_build_object('bonds_redeemed', public.redeem_matured_bonds(v_now));
  end if;
  v_result := v_result || jsonb_build_object('bonds_issued', public.ensure_bond_series());

  -- jobs: AI postings of the running quarter, wages of AI-company jobs in whole hours
  v_result := v_result || jsonb_build_object('quit_notices', public.process_quit_notices(null));
  v_result := v_result || jsonb_build_object('share_offers', public.close_due_offers(null));
  v_result := v_result || jsonb_build_object('job_postings', public.refresh_ai_job_postings(),
                                             'salaries_paid', public.accrue_salaries(null));

  -- artworks (ADR-080): due auctions are settled, the gallery starts the auctions of the day
  v_result := v_result || jsonb_build_object('artworks', public.artworks_run_due());

  -- rich list snapshot every richList.snapshotMinutes (rank news, 24 h changes, state missions)
  v_result := v_result || jsonb_build_object('rich_list', public.rich_list_snapshot(false));

  -- daily maintenance (first run per UTC day)
  insert into public.job_runs (job_name, run_key) values ('maintenance', to_char(now() at time zone 'UTC', 'YYYY-MM-DD'))
  on conflict (job_name, run_key) do nothing
  returning id into v_run;
  if v_run is not null then
    v_result := v_result || jsonb_build_object('maintenance', public.run_maintenance());
    -- price_ticks: keep about one day (candles hold the history), cron log: one day
    perform public.maintain_price_tick_partitions(3, 1);
    if to_regclass('cron.job_run_details') is not null then
      begin
        execute 'delete from cron.job_run_details where end_time < now() - interval ''1 day''';
      exception when others then
        raise warning 'NEXA: could not prune cron.job_run_details: %', sqlerrm;
      end;
    end if;
    delete from public.job_runs j where j.job_name = 'maintenance' and j.started_at < now() - interval '30 days';
    update public.job_runs set status = 'succeeded', finished_at = now() where id = v_run;
  end if;
  return v_result;
end;
$$;

-- ---------------------------------------------------------------------------
-- L. Unlock row (seed.sql has it too; levels exist only after seed.sql on a new database)
-- ---------------------------------------------------------------------------
insert into public.unlocks (key, level, title, description, icon_key, intro_mission_key, sort_order)
select 'artworks', 8, 'Artworks', 'Male eigene Pixel-Kunst, sammle Unikate und biete in Auktionen mit.', 'unlock_art', null, 81
 where exists (select 1 from public.levels l where l.level = 8)
on conflict (key) do nothing;
insert into public.player_unlocks (player_id, unlock_key)
select p.id, 'artworks' from public.profiles p
 where p.level >= 8 and exists (select 1 from public.unlocks u where u.key = 'artworks')
on conflict do nothing;

-- ---------------------------------------------------------------------------
-- M. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.artworks_assign_serial()', 'public.api_error(text)', 'public.artwork_valid(jsonb)',
    'public.artwork_create_cost_cents(integer)', 'public.artwork_min_bid_cents(bigint, bigint)',
    'public.artwork_hot(bigint, bigint, timestamptz, timestamptz)', 'public.artwork_code(bigint)',
    'public.artwork_title_violation(text)', 'public.artworks_require_unlock(uuid)', 'public.player_art_value_cents(uuid)',
    'public.artwork_gallery_start_cents(text)', 'public.artwork_json(uuid, uuid)', 'public.artwork_settle_auction(uuid)',
    'public.artworks_gallery_schedule(timestamptz)', 'public.artworks_run_due()', 'public.artworks_wipe_player(uuid, text)',
    'public.get_artworks(text, text, boolean, integer, integer)', 'public.get_artwork(uuid)', 'public.get_art_studio()',
    'public.get_art_rankings(integer)', 'public.get_collection(text)', 'public.create_artwork(uuid, text, jsonb)',
    'public.like_artwork(uuid, uuid, boolean)', 'public.start_auction(uuid, uuid, bigint, integer)',
    'public.cancel_auction(uuid, uuid)', 'public.bid_artwork(uuid, uuid, bigint)',
    'public.player_net_worth_cents(uuid)', 'public.rich_list_entries()', 'public.account_wipe(uuid, text)',
    'public.run_due_jobs()'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  foreach f in array array[
    'public.get_artworks(text, text, boolean, integer, integer)', 'public.get_artwork(uuid)', 'public.get_art_studio()',
    'public.get_art_rankings(integer)', 'public.get_collection(text)', 'public.create_artwork(uuid, text, jsonb)',
    'public.like_artwork(uuid, uuid, boolean)', 'public.start_auction(uuid, uuid, bigint, integer)',
    'public.cancel_auction(uuid, uuid)', 'public.bid_artwork(uuid, uuid, bigint)'
  ] loop
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end;
$$;

commit;
